insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('omeprazole','Omeprazole','أوميبرازول','A','Proton pump inhibitor','PO / IV','A02BC01','Beginner','خفض إفراز حمض المعدة في الاستطبابات المناسبة مثل GERD والقرحة وبعض أنظمة H. pylori.','يثبط H+/K+-ATPase في الخلايا الجدارية للمعدة بشكل غير عكوس، فيقل إفراز الحمض.','صداع، اضطرابات هضمية؛ مع الاستعمال الطويل قد تظهر مشكلات مرتبطة بنقص بعض المغذيات أو المغنيسيوم حسب الحالة.','فرط الحساسية وبعض التداخلات الدوائية؛ راجع المنتج وحالة المريض.','عادةً يؤخذ قبل الطعام. لا تستخدمه طويلًا دون مراجعة الحاجة.','الاستجابة، الأعراض المنذرة، والحاجة المستمرة للعلاج.','الـPPI أقوى في كبح الحمض من H2 blockers.',null,'["GERD","PPI","Ulcer"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('metformin','Metformin','ميتفورمين','A','Biguanide','PO','A10BA02','Beginner','دواء أساسي شائع للسكري النوع الثاني عند المرضى المناسبين.','يقلل إنتاج الغلوكوز الكبدي ويحسن حساسية الإنسولين.','غثيان، إسهال، انزعاج بطني؛ الحماض اللبني نادر لكنه خطير في سياقات محددة.','تقييم وظيفة الكلية ضروري؛ توجد موانع واحتياطات مرتبطة بالحالات الحادة والقصور الكلوي.','تناوله مع الطعام يحسن التحمل. لا تستخدمه اعتمادًا على قيمة سكر واحدة.','eGFR، HbA1c/سكر الدم، التحمل الهضمي، وB12 عند وجود عوامل خطورة.','خطر نقص السكر أقل عند استخدامه منفردًا مقارنةً بمحفزات الإنسولين.',null,'["Diabetes","T2DM"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ondansetron','Ondansetron','أوندانسيترون','A','5-HT3 receptor antagonist','PO / IV','A04AA01','Intermediate','الوقاية/العلاج من الغثيان والقيء في سياقات سريرية محددة.','يحصر مستقبلات 5-HT3 المحيطية والمركزية.','صداع، إمساك؛ قد يطيل QT لدى بعض المرضى.','فرط الحساسية؛ الحذر مع أدوية/حالات تزيد QT.','لا تعالج السبب الأساسي للقيء؛ استخدم حسب الاستطباب.','الأعراض، الترطيب، وعوامل خطر QT.','فكر بخطر إطالة QT عند اجتماع عوامل خطورة.',null,'["Nausea","Vomiting"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('loperamide','Loperamide','لوبيراميد','A','Peripheral opioid receptor agonist','PO','A07DA03','Beginner','تقليل الإسهال الحاد غير المعقد في البالغين وبعض الاستطبابات الأخرى.','يقلل حركة الأمعاء وإفراز السوائل عبر مستقبلات أفيونية محيطية.','إمساك، مغص؛ الجرعات المفرطة قد ترتبط باضطرابات نظم خطرة.','لا يستخدم عند وجود إسهال دموي/حمى أو اشتباه عدوى غازية إلا بتقييم مناسب.','السوائل وتعويض الأملاح مهمان. لا تتجاوز المدة/الجرعة الموصى بها.','الترطيب، علامات العدوى، واستمرار الإسهال.','مضاد الإسهال ليس مناسبًا لكل إسهال.',null,'["Diarrhea"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('warfarin','Warfarin','وارفارين','B','Vitamin K antagonist','PO','B01AA03','Advanced','مضاد تخثر في استطبابات محددة مثل بعض حالات AF وVTE والصمامات الميكانيكية.','يثبط VKORC1 ويقلل تصنيع عوامل التخثر المعتمدة على فيتامين K.','النزف أهم خطر؛ نادرًا مضاعفات أخرى مثل النخر الجلدي.','نزف فعال وموانع مرتبطة بالحمل واستطباب المريض والتداخلات.','ثبات نمط الغذاء مهم، خصوصًا مدخول فيتامين K. يجب الالتزام بفحوص INR.','INR، النزف، التداخلات، وتغيرات النظام الغذائي/الدوائي.','Warfarin دواء يحتاج titration ومتابعة وليس جرعة ثابتة.',null,'["Anticoagulant","INR"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('clopidogrel','Clopidogrel','كلوبيدوغريل','B','P2Y12 inhibitor','PO','B01AC04','Intermediate','منع الأحداث الخثرية الشريانية في استطبابات مناسبة مثل ACS وبعض المرضى بعد PCI.','يثبط مستقبل P2Y12 للـADP على الصفائح بشكل غير عكوس.','نزف، كدمات؛ نادرًا نقص صفائح/مشكلات دموية.','نزف فعال وموانع أخرى حسب المنتج والاستطباب.','لا توقفه ذاتيًا بعد تركيب دعامة أو ضمن خطة DAPT.','علامات النزف، الالتزام، والتداخلات.','هو prodrug ويتأثر استقلابه بـCYP2C19.',null,'["Antiplatelet","P2Y12"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ferrous-sulfate','Ferrous sulfate','كبريتات الحديد','B','Oral iron','PO','B03AA07','Beginner','علاج نقص الحديد عندما يكون العلاج الفموي مناسبًا.','يوفر الحديد لتكوين الهيموغلوبين وتصحيح مخزون الحديد تدريجيًا.','غثيان، إمساك، براز داكن.','لا تعالج فقر الدم مجهول السبب قبل تقييم السبب.','قد يحسن أخذه بعيدًا عن بعض الأطعمة/الأدوية الامتصاص، لكن التحمل مهم.','Hb، ferritin/iron studies بحسب الحالة، والتحمل والالتزام.','تحسن Hb يسبق استعادة مخزون الحديد؛ أكمل العلاج حسب الخطة.',null,'["Anemia","Iron"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('amlodipine','Amlodipine','أملوديبين','C','Dihydropyridine calcium-channel blocker','PO','C08CA01','Beginner','ارتفاع ضغط الدم والذبحة الصدرية في المرضى المناسبين.','يثبط قنوات الكالسيوم من نوع L في العضلات الملساء الوعائية فيسبب توسعًا وعائيًا.','وذمة طرفية، صداع، احمرار، دوخة.','الحذر في بعض الحالات القلبية والضغطية؛ راجع الموانع الفردية.','دواء يومي طويل الأمد؛ لا توقفه عند تحسن القراءة فقط.','ضغط الدم، الوذمة، الدوخة والاستجابة.','الوذمة الطرفية شائعة ولا تعني وحدها فشل القلب.',null,'["Hypertension","CCB"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('losartan','Losartan','لوسارتان','C','Angiotensin II receptor blocker','PO','C09CA01','Intermediate','ارتفاع ضغط الدم واستطبابات أخرى مثل بعض مرضى قصور القلب/اعتلال الكلية.','يحصر مستقبل AT1 للأنجيوتنسين II، فيقل التضيق الوعائي والألدوستيرون.','دوخة، ارتفاع بوتاسيوم، تغيرات وظيفة الكلية.','الحمل؛ الحذر مع تضيق الشرايين الكلوية وبعض الحالات الأخرى.','لا تتناول مكملات البوتاسيوم دون استشارة.','ضغط الدم، K+، creatinine/eGFR.','ARBs لا تسبب السعال الجاف بنفس معدل ACE inhibitors.',null,'["ARB","Hypertension"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('atorvastatin','Atorvastatin','أتورفاستاتين','C','HMG-CoA reductase inhibitor','PO','C10AA05','Intermediate','خفض LDL وتقليل الخطر القلبي الوعائي حسب مستوى الخطورة.','يثبط HMG-CoA reductase ويزيد التقاط LDL في الكبد.','ألم عضلي، ارتفاع إنزيمات الكبد؛ اعتلال عضلي شديد نادر.','الحمل وبعض الحالات/التداخلات؛ راجع المنتج.','أبلغ عن ألم عضلي شديد أو غير معتاد، وتحقق من التداخلات.','Lipid panel، الأعراض العضلية ووظائف الكبد عند الحاجة السريرية.','اختيار شدة الستاتين يعتمد على خطر المريض والهدف وليس رقمًا منفردًا.',null,'["Statin","Lipid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('furosemide','Furosemide','فوروسيميد','C','Loop diuretic','PO / IV','C03CA01','Intermediate','الوذمة المرتبطة بقصور القلب وحالات أخرى، وبعض الاستعمالات في الضغط.','يثبط NKCC2 في الثلث الصاعد الغليظ من عروة Henle.','نقص K+/Na+، جفاف، انخفاض ضغط؛ سمية أذنية في ظروف معينة.','موانع مرتبطة بالجفاف الشديد واضطرابات الأملاح وبعض الحالات.','راقب السوائل والدوخة. توقيت الجرعة يؤثر على التبول.','الوزن، الضغط، Na/K/creatinine، الحالة الحجمية.','راقب electrolytes والوظيفة الكلوية خصوصًا مع الجرعات الأعلى.',null,'["Diuretic","Edema"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('hydrocortisone','Hydrocortisone topical','هيدروكورتيزون موضعي','D','Low-potency topical corticosteroid','Topical','D07AA02','Beginner','أمراض التهابية جلدية خفيفة مناسبة للعلاج الموضعي.','يثبط وسائط الالتهاب والمناعة محليًا.','ضمور الجلد مع الإفراط/الطول، تفاقم عدوى فطرية محتملة.','لا يوضع عشوائيًا على عدوى غير معالجة أو قرب العين دون توجيه.','طبقة رقيقة ومدة مناسبة؛ تجنب الاستخدام المفرط.','التحسن، تهيج الجلد، وظهور علامات عدوى.','قوة الستيرويد وموضع الجسم ومدة الاستخدام مهمة.',null,'["Eczema","Steroid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('clotrimazole','Clotrimazole','كلوتريمازول','D','Imidazole antifungal','Topical','D01AC01','Beginner','عدوى فطرية سطحية مناسبة لمضادات الفطريات الموضعية.','يقلل تصنيع ergosterol الفطري عبر تثبيط 14-α-demethylase.','تهيج موضعي، حرقان أو احمرار.','فرط الحساسية؛ لا تستخدمه لأي طفح دون تشخيص مناسب.','الالتزام بمدة العلاج مهم حتى بعد تحسن الأعراض بحسب المنتج.','الاستجابة والتهيج.','المظهر وحده لا يكفي دائمًا لتمييز الفطريات عن الإكزيما.',null,'["Fungal","Topical"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('tretinoin','Tretinoin topical','تريتينوين موضعي','D','Topical retinoid','Topical','D10AD01','Intermediate','علاج حب الشباب وبعض الاستطبابات الجلدية المحددة.','ينظم تمايز الخلايا الكيراتينية ويقلل تشكل الكوميدونات.','جفاف، تقشر، تهيج وحساسية للشمس.','الحمل يتطلب مراجعة/تجنب حسب المنتج والسياق؛ تجنب المناطق المتهيجة بشدة.','يبدأ تدريجيًا، مع واقٍ شمسي وترطيب مناسب.','التهيج والاستجابة خلال أسابيع.','قد يسوء حب الشباب ظاهريًا في البداية قبل التحسن.',null,'["Acne","Retinoid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('tamsulosin','Tamsulosin','تامسولوسين','G','Alpha-1 blocker','PO','G04CA02','Intermediate','أعراض تضخم البروستات الحميد.','يحصر مستقبلات α1A في العضلات الملساء للبروستات وعنق المثانة.','دوخة، انخفاض ضغط وضعي، اضطراب القذف؛ متلازمة iris floppy أثناء بعض جراحات العين.','الحذر مع انخفاض الضغط ومشاركة أدوية موسعة للأوعية.','النهوض ببطء؛ أخبر طبيب العيون قبل جراحة الساد.','الأعراض البولية والدوخة والضغط.','يحسن الأعراض لكنه لا يصغر البروستات بحد ذاته.',null,'["BPH","Alpha blocker"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('sildenafil','Sildenafil','سيلدينافيل','G','PDE-5 inhibitor','PO','G04BE03','Intermediate','ضعف الانتصاب وبعض الاستطبابات الرئوية بمنتجات/جرعات مختلفة.','يثبط PDE-5 ويرفع cGMP في العضلات الملساء، مع تحسين الاستجابة للـNO.','صداع، احمرار، عسر هضم، تغيرات بصرية عابرة.','ممنوع مع النترات؛ الحذر مع خافضات الضغط وبعض الحالات القلبية.','لا يجمع مع nitrates. يحتاج إثارة جنسية لتحقيق التأثير في ED.','الضغط، الفعالية والآثار الجانبية.','أهم سؤال دوائي قبل الصرف: هل يستخدم nitrate؟',null,'["ED","PDE5"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('levothyroxine','Levothyroxine','ليفوثيروكسين','H','Thyroid hormone','PO / IV','H03AA01','Intermediate','قصور الغدة الدرقية واستطبابات درقية محددة.','يعوض T4 ويؤدي إلى تأثيرات درقية بعد تحويل جزء منه إلى T3 محيطيًا.','الزيادة قد تسبب خفقانًا، رجفة، تعرقًا وأرقًا.','تقييم الجرعة مهم خصوصًا في كبار السن ومرضى القلب.','الثبات في التوقيت وطريقة التناول مهم؛ الحديد والكالسيوم قد يقللان الامتصاص.','TSH/FT4 وفق الخطة السريرية.','التبدل بين المنتجات/طرق تناولها قد يغير TSH لدى بعض المرضى.',null,'["Thyroid","T4"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('prednisolone','Prednisolone','بريدنيزولون','H','Systemic corticosteroid','PO','H02AB06','Intermediate','أمراض التهابية ومناعية متعددة بحسب التشخيص.','ينشط مستقبلات glucocorticoid وينظم التعبير الجيني لمجموعة واسعة من وسائط الالتهاب.','ارتفاع السكر والضغط، احتباس سوائل، اضطرابات مزاج ونقص مناعة مع الاستخدام الأطول.','تعتمد على الجرعة والمدة والعدوى والحالة؛ لا يوقف بعد الاستخدام المزمن فجأة.','تناوله حسب الخطة ولا توقفه عشوائيًا بعد الاستخدام المطول.','السكر، الضغط، العدوى، الوزن والعظام وفق المدة.','الجرعة والمدة يغيران مخاطر الستيرويد بصورة كبيرة.',null,'["Steroid","Inflammation"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('amoxicillin','Amoxicillin','أموكسيسيلين','J','Aminopenicillin β-lactam','PO','J01CA04','Beginner','عدوى بكتيرية حساسة وفق موقع العدوى والممرض والإرشادات المحلية.','يثبط تصنيع جدار الخلية بالارتباط مع PBPs.','إسهال، غثيان، طفح؛ التحسس قد يكون شديدًا.','حساسية شديدة سابقة للبنسلينات/بعض β-lactams حسب نوع التفاعل.','لا يُستخدم للعدوى الفيروسية. التزم بالوصفة، وراقب الإسهال الشديد.','الاستجابة، الحساسية، الإسهال، والوظيفة الكلوية عند الحاجة.','اسأل عن طبيعة حساسية البنسلين، لا تكتفِ بكلمة “حساسية”.',null,'["Antibiotic","Penicillin"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('azithromycin','Azithromycin','أزيثروميسين','J','Macrolide','PO / IV','J01FA10','Intermediate','عدوى بكتيرية مختارة وحسب الإرشادات والمقاومة المحلية.','يرتبط بالوحدة 50S الريبوسومية ويثبط تصنيع البروتين.','اضطرابات هضمية؛ قد يطيل QT لدى بعض المرضى.','الحذر مع تاريخ اضطراب نظم/إطالة QT والتداخلات المناسبة.','لا تستخدمه لمجرد التهاب الحلق دون تقييم السبب.','الاستجابة، الأعراض الهضمية وعوامل خطر QT.','المقاومة والاستخدام غير المناسب للمضادات مشكلة علاجية حقيقية.',null,'["Macrolide","Antibiotic"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('fluconazole','Fluconazole','فلوكونازول','J','Triazole antifungal','PO / IV','J02AC01','Intermediate','عدوى فطرية مناسبة حسب الممرض والموقع.','يثبط تصنيع ergosterol الفطري عبر CYP51/14-α-demethylase.','غثيان، ارتفاع إنزيمات الكبد، وتداخلات دوائية متعددة.','تداخلات مهمة وبعض حالات QT/الكبد؛ راجع المنتج.','الالتزام بالمدة والتحقق من التداخلات مهم.','الاستجابة، وظائف الكبد عند الحاجة، والتداخلات.','Fluconazole inhibitor دوائي مهم لبعض CYPs.',null,'["Antifungal","Azole"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('acyclovir','Acyclovir','أسيكلوفير','J','Antiviral','PO / IV / Topical','J05AB01','Intermediate','عدوى HSV وVZV في سياقات علاجية مناسبة.','نظير نوكليوزيدي يُفعّل في الخلايا المصابة ويثبط DNA polymerase الفيروسي.','غثيان؛ سمية كلوية خاصة مع IV/الجفاف في سياقات معينة.','الحذر مع القصور الكلوي والجفاف.','البدء المبكر قد يفيد في بعض العدوى؛ اشرب سوائل مناسبة حسب حالتك.','وظيفة الكلية والاستجابة والجرعة حسب eGFR.','التحويل من جرعة ثابتة إلى renal-adjusted dosing مهم في القصور الكلوي.',null,'["Antiviral","HSV"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ibuprofen','Ibuprofen','إيبوبروفين','M','NSAID','PO','M01AE01','Beginner','الألم والالتهاب والحمى عند المريض المناسب.','يثبط COX ويقلل تصنيع البروستاغلاندينات.','عسر هضم، قرحة/نزف، تأثيرات كلوية، احتباس سوائل.','القرحة/النزف، بعض حالات الكلية والقلب والحمل المتأخر وغيرها.','تجنب الجمع العشوائي بين NSAIDs، وانتبه للتجفاف.','الألم، الضغط، النزف ووظائف الكلية عند الاستخدام المطول.','أقل جرعة فعالة لأقصر مدة مناسبة.',null,'["NSAID","Analgesic"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('allopurinol','Allopurinol','ألوبورينول','M','Xanthine oxidase inhibitor','PO','M04AA01','Intermediate','خفض اليورات في النقرس وفرط حمض اليوريك في الاستطبابات المناسبة.','يثبط xanthine oxidase ويقلل إنتاج حمض اليوريك.','طفح؛ نادرًا hypersensitivity syndrome شديد.','الحذر الشديد عند بدء العلاج ومع بعض العوامل الجينية/الكلوية.','لا تستخدمه لعلاج نوبة الألم الحادة كمسكن؛ بدء العلاج يحتاج خطة مناسبة.','Serum urate، الكلية، الطفح والالتزام.','الهدف عادة هو urate target-based وليس مجرد إزالة الألم.',null,'["Gout","Urate"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('alendronate','Alendronate','أليندرونات','M','Bisphosphonate','PO','M05BA04','Intermediate','علاج/وقاية هشاشة العظام في المرضى المناسبين.','يثبط نشاط osteoclast ويقلل ارتشاف العظم.','تهيج مريئي واضطرابات هضمية؛ مخاطر نادرة مع الاستخدام الطويل.','مشكلات مريئية معينة وعدم القدرة على الوقوف/الجلوس بعد الجرعة، وغيرها.','يؤخذ صباحًا مع ماء فقط والبقاء قائمًا لمدة محددة حسب المنتج.','BMD حسب الخطة، وظائف الكلية، الكالسيوم/فيتامين D حسب الحالة.','طريقة التناول جزء من فعالية وسلامة الدواء.',null,'["Osteoporosis","Bisphosphonate"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('paracetamol','Paracetamol','باراسيتامول / أسيتامينوفين','N','Non-opioid analgesic / antipyretic','PO / IV / PR','N02BE01','Beginner','الألم والحمى في الجرعات المناسبة.','التأثير المركزي المسكن وخافض الحرارة؛ الآلية الدقيقة متعددة العوامل.','سمية كبدية خطرة في الجرعات الزائدة أو مع عوامل خطورة معينة.','الجرعات العالية/مرض الكبد تستلزم تقييمًا حذرًا.','انتبه لتكراره داخل مستحضرات البرد والزكام.','إجمالي الجرعة اليومية وعوامل خطر الكبد.','أكثر خطأ شائع: الجمع بين أكثر من منتج يحتوي paracetamol.',null,'["Pain","Fever"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('sertraline','Sertraline','سيرترالين','N','SSRI','PO','N06AB06','Intermediate','الاكتئاب وبعض اضطرابات القلق وغيرها حسب التشخيص.','يثبط إعادة امتصاص السيروتونين.','غثيان، اضطراب نوم، آثار جنسية؛ مخاطر نادرة مثل serotonin syndrome.','ممنوع مع MAOIs والتداخلات المهمة الأخرى.','التحسن يحتاج وقتًا؛ لا توقف فجأة دون خطة.','الاستجابة، الآثار الجانبية والتداخلات، والمزاج حسب السياق.','الفعالية لا تُحكم عادة خلال أول عدة أيام.',null,'["SSRI","Depression"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('levetiracetam','Levetiracetam','ليفيتيراسيتام','N','Antiseizure medicine','PO / IV','N03AX14','Intermediate','أنواع متعددة من الصرع حسب التشخيص.','يرتبط ببروتين SV2A ويعدل النقل المشبكي.','نعاس، دوخة وتغيرات سلوكية عند بعض المرضى.','الحذر في قصور الكلية وتعديل الجرعة حسب eGFR.','لا يوقف فجأة. انتبه للتغيرات المزاجية والسلوكية.','النوبات، السلوك ووظيفة الكلية.','تعديل الجرعة في القصور الكلوي مهم.',null,'["Epilepsy","SV2A"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('quetiapine','Quetiapine','كويتيابين','N','Atypical antipsychotic','PO','N05AH04','Advanced','اضطرابات نفسية محددة مثل الفصام واضطراب ثنائي القطب وبعض الاستطبابات حسب المنتج.','تأثيرات متعددة على 5-HT2A وD2 ومستقبلات أخرى.','نعاس، زيادة وزن، تغيرات استقلابية وانخفاض ضغط وضعي.','تعتمد على المنتج والحالة؛ الحذر في عوامل الخطر القلبية والاستقلابية.','النعاس شائع؛ تجنب القيادة إذا تأثر الوعي.','الوزن، السكر/الدهون، الضغط والأعراض.','راقب cardiometabolic burden مع الاستعمال المزمن.',null,'["Antipsychotic","Psychiatry"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('albendazole','Albendazole','ألبيندازول','P','Benzimidazole anthelmintic','PO','P02CA03','Beginner','بعض الديدان المعوية حسب نوع الطفيلي والجرعة المعتمدة.','يثبط تكوين الأنابيب الدقيقة في الطفيلي ويؤثر في امتصاص الغلوكوز.','أعراض هضمية؛ مراقبة الكبد في بعض العلاجات الطويلة.','تعتمد على الطفيلي والحمل والمدة؛ راجع المنتج.','الجرعة تختلف كثيرًا حسب الطفيلي.','الاستجابة والوظائف المختبرية عند العلاج المطول.','لا توجد جرعة واحدة صالحة لكل الديدان.',null,'["Worms","Anthelmintic"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('permethrin','Permethrin 5%','بيرمثرين 5%','P','Topical pyrethroid','Topical','P03AC04','Beginner','علاج الجرب في الاستطبابات المناسبة.','يعطل قنوات الصوديوم العصبية في الطفيليات.','حرقان وتهيج موضعيان.','الحذر بحسب العمر والمنتج والحساسية.','تطبيق صحيح على مناطق الجسم المناسبة وعلاج المخالطين/الملابس حسب الإرشادات.','الحكة قد تستمر بعد القضاء على الطفيلي؛ قيّم الفشل بعناية.','تقنية التطبيق والتعامل مع المخالطين جزء من العلاج.',null,'["Scabies","Topical"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('salbutamol','Salbutamol','سالبوتامول','R','Short-acting β2 agonist','Inhaled','R03AC02','Beginner','تخفيف سريع لتشنج القصبات في الربو وبعض حالات الانسداد القابل للعكس.','ينشط β2 في العضلات الملساء للشعب الهوائية فيسبب توسعًا قصبيًا.','رجفة، خفقان، تسرع قلب، نقص بوتاسيوم بجرعات عالية.','الحذر مع بعض اضطرابات النظم والتأثيرات القلبية.','تعليم تقنية الاستنشاق مهم؛ الإفراط في الاستخدام علامة تستدعي مراجعة السيطرة.','الأعراض، تكرار الاستخدام والتقنية.','SABA مسكن سريع وليس بديلًا للعلاج المضاد للالتهاب عند الحاجة.',null,'["Asthma","SABA"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('budesonide','Budesonide inhaled','بوديزونيد مستنشق','R','Inhaled corticosteroid','Inhaled','R03BA02','Intermediate','السيطرة طويلة الأمد على الربو وبعض الاستطبابات الأخرى بحسب المنتج.','يقلل الالتهاب الهوائي ويخفض فرط الاستجابة.','بحة وداء المبيضات الفموي؛ آثار جهازية أقل من الستيرويدات الجهازية لكنها ممكنة.','تعتمد على المنتج؛ ليس دواء إنقاذ للهجمة الحادة.','اغسل الفم بعد الاستخدام وعلّم تقنية الجهاز.','السيطرة على الأعراض، التقنية والآثار الجانبية.','التقنية والالتزام أهم من تبديل الجهاز عشوائيًا.',null,'["Asthma","ICS"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('cetirizine','Cetirizine','سيتريزين','R','Second-generation H1 antihistamine','PO','R06AE07','Beginner','التهاب الأنف التحسسي والشرى.','يحصر مستقبلات H1 المحيطية ويخفف الحكة والعطاس وسيلان الأنف.','نعاس عند بعض المرضى، جفاف الفم.','الحذر في القصور الكلوي وبعض المرضى الحساسين للنعاس.','قد يسبب النعاس؛ اختبر تأثيره قبل القيادة.','الأعراض والنعاس.','مضاد H1 من الجيل الثاني أقل تسبيبًا للنعاس من كثير من الجيل الأول.',null,'["Allergy","Antihistamine"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('timolol','Timolol ophthalmic','تيمولول عيني','S','Ophthalmic beta blocker','Ophthalmic','S01ED01','Intermediate','خفض ضغط العين في الجلوكوما المناسبة.','يقلل إنتاج aqueous humor عبر حصر β receptors.','قد يسبب بطء قلب/تشنج قصبي بسبب الامتصاص الجهازي.','الربو/Bradycardia/heart block وبعض الحالات بحسب المنتج.','إغلاق العين أو الضغط على القناة الدمعية بعد القطرة قد يقلل الامتصاص الجهازي.','IOP والنبض/الأعراض التنفسية عند عوامل الخطورة.','دواء عيني لا يعني غياب التأثيرات الجهازية.',null,'["Glaucoma","Eye drops"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('artificial-tears','Artificial tears','دموع صناعية','S','Ocular lubricant','Ophthalmic','S01XA20','Beginner','تخفيف أعراض جفاف العين.','تزيد ترطيب سطح العين وتقلل الاحتكاك.','تشوش مؤقت أو تهيج نادر.','تعتمد على التركيبة؛ الحذر في المنتجات المحتوية على مواد حافظة عند الاستخدام المتكرر.','استخدم النوع المناسب، وتجنب ملامسة طرف العبوة للعين.','الأعراض واستمرارها أو ظهور ألم/احمرار شديد.','الأعراض المستمرة أو الشديدة تحتاج تقييم سبب جفاف العين.',null,'["Dry eye"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('naloxone','Naloxone','نالوكسون','V','Opioid antagonist','IM / IV / IN','V03AB15','Advanced','عكس تثبيط التنفس الناتج عن الجرعة الزائدة من الأفيونات.','مضاد لمستقبلات opioid ويزيح الأفيونات عن المستقبلات.','قد يسبب انسحابًا حادًا في المعتمدين على الأفيونات؛ عودة التثبيط التنفسي ممكنة حسب مدة الأفيون.','الحذر من شدة الانسحاب؛ لا يؤخر إنقاذ الحياة.','استخدمه مع استدعاء الإسعاف ودعم مجرى الهواء والتنفس.','التنفس والاستجابة والحاجة لتكرار الجرعات حسب البروتوكول.','نصف عمر النالوكسون قد يكون أقصر من بعض الأفيونات.',null,'["Antidote","Opioid overdose"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('activated-charcoal','Activated charcoal','الفحم المنشط','V','Adsorbent','PO / NG','V03AB25','Advanced','يُستخدم فقط في حالات محددة من التسمم وبشروط زمنية وسلامة معينة.','يمتَص بعض السموم في الجهاز الهضمي ويحد من امتصاصها.','خطر aspiration، قيء وإمساك.','تسممات معينة لا يمتصها، أو وجود خطر شفط/انسداد بحسب الحالة.','ليس “ترياقًا عامًا” ولا يُعطى منزليًا لكل ابتلاع.','مجرى الهواء والحالة السمية وتطور الأعراض.','اختيار المريض والزمن والمادة أهم من فكرة “إعطاء الفحم”.',null,'["Toxicology","Poisoning"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('pantoprazole','Pantoprazole','بانتوبرازول','A','Proton pump inhibitor','PO / IV',null,'Intermediate','GERD، القرحة، وفرط إفراز الحمض في الاستطبابات المناسبة','يثبط H+/K+-ATPase في الخلايا الجدارية ويقلل إفراز الحمض.','صداع، إسهال/إمساك، وآثار مرتبطة بالاستعمال الطويل في بعض المرضى.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','يُؤخذ عادة قبل الطعام؛ لا تُطيل الاستخدام دون مراجعة السبب.','الأعراض، الاستجابة، والحاجة إلى الاستمرار.','PPI طويل المفعول؛ راقب الحاجة للاستخدام المزمن.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["GERD","PPI"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('esomeprazole','Esomeprazole','إيزوميبرازول','A','Proton pump inhibitor','PO / IV',null,'Intermediate','GERD والقرحة وحالات فرط إفراز الحمض المناسبة','يثبط مضخة البروتون بشكل غير عكوس ويقلل الحموضة.','صداع واضطرابات هضمية؛ مخاطر الاستعمال الطويل تعتمد على المريض.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم حسب الوصفة والنشرة الحالية، وانتبه لطريقة الاستعمال والتداخلات.','الاستجابة والآثار الجانبية والعوامل الخاصة بالمريض.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["GERD","PPI"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('famotidine','Famotidine','فاموتيدين','A','H2-receptor antagonist','PO / IV',null,'Intermediate','GERD والقرحة وأعراض فرط الحمض في الحالات المناسبة','يحصر مستقبلات H2 في الخلايا الجدارية ويخفض إفراز الحمض.','صداع، دوخة، إسهال/إمساك؛ قد تتراكم التأثيرات في القصور الكلوي.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','قد يؤخذ مع أو دون طعام حسب المنتج؛ انتبه لتعديل الجرعة في القصور الكلوي.','الاستجابة ووظيفة الكلية عند الحاجة.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["H2 blocker","GERD"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('sucralfate','Sucralfate','سوكرالفات','A','Mucosal protective agent','PO',null,'Intermediate','القرحة الهضمية وبعض حالات التهاب المخاطية','يشكل حاجزًا واقيًا فوق القرحة ويرتبط بالأنسجة المتأذية في الوسط الحمضي.','إمساك؛ قد يقلل امتصاص أدوية أخرى.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','افصل بينه وبين أدوية أخرى بحسب التداخلات لأنه قد يعيق الامتصاص.','التئام الأعراض والالتزام والتداخلات.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Ulcer","Mucosal protection"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('bismuth-subsalicylate','Bismuth subsalicylate','بزموت سبساليسيلات','A','Antidiarrheal / gastroprotective','PO',null,'Intermediate','إسهال حاد غير معقد وبعض أنظمة علاج H. pylori','له تأثيرات مضادة للميكروبات ومضادة للإفراز وحماية للمخاطية.','اسوداد اللسان والبراز، إمساك؛ سمية الساليسيلات عند الإفراط.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','اسوداد البراز أو اللسان قد يحدث؛ تجنب استخدامه بلا تقييم عند الأطفال وبعض الحالات.','الترطيب واستمرار الإسهال وعلامات السمية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Diarrhea","H pylori"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('metoclopramide','Metoclopramide','ميتوكلوبراميد','A','D2 antagonist / prokinetic','PO / IV / IM',null,'Intermediate','الغثيان والقيء وبعض اضطرابات حركة المعدة في استطبابات محددة','يحصر D2 ويعزز الحركة المعدية؛ له تأثير مركزي مضاد للقيء.','نعاس، إسهال، أعراض خارج هرمية؛ خلل حركي متأخر مع الاستخدام المزمن.','تجنب/احذر في انسداد أو نزف هضمي، وبعض اضطرابات الحركة وموانع أخرى.','استخدم أقصر مدة مناسبة وتجنب القيادة عند النعاس.','الفعالية والأعراض خارج الهرمية ومدة العلاج.','ليس دواءً مناسبًا للاستخدام المزمن العشوائي.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antiemetic","Prokinetic"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('domperidone','Domperidone','دومبيريدون','A','Peripheral D2 antagonist','PO',null,'Intermediate','الغثيان والقيء في بعض الأنظمة التنظيمية وبشروط محددة','حاصر D2 محيطي يقلل إشارات القيء ويزيد حركة الجهاز الهضمي.','جفاف الفم، تشنجات؛ خطر اضطراب النظم/إطالة QT مهم في فئات معينة.','لا يُستخدم دون الانتباه للـQT والتداخلات وموانع القلب المعروفة؛ التوفر والاستطباب يختلفان بين البلدان.','تحقق من القوانين المحلية والتداخلات القلبية قبل الاستخدام.','الاستجابة وعوامل خطر QT والقلب.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antiemetic","QT"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('bisacodyl','Bisacodyl','بيساكوديل','A','Stimulant laxative','PO / PR',null,'Intermediate','الإمساك أو تحضير الأمعاء في استطبابات محددة','ينشط حركة القولون ويزيد إفراز الماء والإلكتروليتات.','مغص، إسهال، اضطراب الأملاح مع الإفراط.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','لا تعتمد على الملينات المنبهة يوميًا دون تقييم السبب.','التبرز، الترطيب، الشوارد عند الاستخدام المطول.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Constipation"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('polyethylene-glycol','Polyethylene glycol','بولي إيثيلين غلايكول','A','Osmotic laxative','PO',null,'Intermediate','الإمساك المزمن/الحاد في المرضى المناسبين','يسحب الماء إلى القولون ويحسن قوام البراز.','انتفاخ، غازات، إسهال.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم حسب الوصفة والنشرة الحالية، وانتبه لطريقة الاستعمال والتداخلات.','الاستجابة والآثار الجانبية والعوامل الخاصة بالمريض.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Constipation","PEG"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('lactulose','Lactulose','لاكتولوز','A','Osmotic laxative','PO',null,'Intermediate','الإمساك واعتلال الدماغ الكبدي ضمن بروتوكولات محددة','يتخمر في القولون ويسحب الماء؛ يقلل امتصاص الأمونيا في اعتلال الدماغ الكبدي.','غازات، مغص، إسهال واضطراب أملاح مع الإفراط.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','في اعتلال الدماغ الكبدي يُضبط حسب الهدف السريري وعدد مرات التبرز.','التبرز والشوارد؛ وفي الاعتلال الكبدي الحالة العقلية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Constipation","Hepatic encephalopathy"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('senna','Senna','سينا','A','Stimulant laxative','PO',null,'Intermediate','الإمساك عند الحاجة','مستقلباتها تنشط القولون وتزيد الحركة والإفراز.','مغص وإسهال واضطراب أملاح مع الإفراط.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم حسب الوصفة والنشرة الحالية، وانتبه لطريقة الاستعمال والتداخلات.','الاستجابة والآثار الجانبية والعوامل الخاصة بالمريض.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Constipation"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('dicyclomine','Dicyclomine','ديسيكلومين','A','Antimuscarinic antispasmodic','PO / IM',null,'Intermediate','تقلصات الأمعاء/IBS في الاستطبابات المناسبة','يقلل التقلص عبر حصر التأثير المسكاريني على العضلات الملساء.','جفاف الفم، إمساك، تشوش رؤية، احتباس بول.','الحذر في الجلوكوما ضيقة الزاوية واحتباس البول وبعض الحالات.','قد يسبب جفافًا ودوخة وتشوش رؤية.','الأعراض والتحمل والتبول.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["IBS","Antispasmodic"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('mesalamine','Mesalamine','ميسالامين','A','5-ASA anti-inflammatory','PO / Rectal',null,'Intermediate','التهاب القولون التقرحي في الاستطبابات المناسبة','تأثير موضعي مضاد للالتهاب في القولون عبر تعديل مسارات حمض الأراكيدونيك وغيرها.','صداع، ألم بطني، ونادرًا التهاب كلوي أو تفاعلات خطرة.','الحذر في أمراض الكلى وبعض اضطرابات الدم/الحساسية للساليسيلات.','لا توقف العلاج دون خطة خاصة في مرض مزمن.','الاستجابة، CBC ووظيفة الكلى حسب المنتج والخطة.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Ulcerative colitis","5-ASA"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('oral-rehydration-salts','Oral rehydration salts','محاليل الإماهة الفموية','A','Oral rehydration therapy','PO',null,'Intermediate','الجفاف الناتج عن الإسهال/القيء في الحالات المناسبة','يعتمد على النقل المقترن للصوديوم والغلوكوز في الأمعاء لتحسين امتصاص الماء.','القيء أو اضطرابات الصوديوم إذا حضرت بشكل خاطئ.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','حضّر بالضبط وفق كمية الماء المحددة ولا تُركز المحلول أكثر من المطلوب.','علامات الجفاف، البول، الوزن والحالة العامة.','السوائل والإلكتروليتات جزء أساسي من علاج الإسهال.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["ORS","Dehydration"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('glimepiride','Glimepiride','غليميبرايد','A','Sulfonylurea','PO',null,'Intermediate','السكري النوع 2 عندما يكون العلاج مناسبًا','يحرض إفراز الإنسولين من خلايا بيتا عبر غلق قنوات KATP.','نقص سكر الدم، زيادة وزن.','الحذر في القصور الكلوي/الكبدي وخطر نقص السكر؛ لا يفيد في T1DM.','لا تتخطى الوجبات مع خطر نقص السكر.','سكر الدم وHbA1c ونوبات نقص السكر.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Diabetes","Sulfonylurea"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('gliclazide','Gliclazide','غليكلازايد','A','Sulfonylurea','PO',null,'Intermediate','السكري النوع 2 في المرضى المناسبين','يحفز إفراز الإنسولين عبر قنوات KATP في خلايا بيتا.','نقص سكر، زيادة وزن، واضطراب هضمي.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','التزم بالوجبات وخطة المراقبة.','سكر الدم وHbA1c ونقص السكر.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Diabetes"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('sitagliptin','Sitagliptin','سيتاغليبتين','A','DPP-4 inhibitor','PO',null,'Intermediate','السكري النوع 2 كعلاج منفرد أو مشارك','يثبط DPP-4 فيزيد incretin activity ويعزز إفراز الإنسولين المعتمد على الغلوكوز ويخفض الغلوكاغون.','أعراض هضمية، التهابات تنفسية خفيفة؛ التهاب بنكرياس نادر.','تعديل الجرعة في القصور الكلوي.','عادة منخفض الخطر لنقص السكر وحده لكن الخطر يزيد مع أدوية أخرى.','HbA1c وسكر الدم ووظيفة الكلية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Diabetes","DPP-4"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('empagliflozin','Empagliflozin','إمباغليفلوزين','A','SGLT2 inhibitor','PO',null,'Intermediate','السكري النوع 2، وتقليل مخاطر قلبية/كلوية في فئات معينة حسب الاستطباب','يمنع إعادة امتصاص الغلوكوز في النبيبات القريبة فيزيد طرحه بالبول.','التهابات تناسلية، جفاف، انخفاض ضغط؛ حماض كيتوني قد يحدث في ظروف معينة.','تقييم وظيفة الكلية وحالات الحماض/الجوع الشديد قبل الاستخدام.','اهتم بالسوائل وتعلم علامات الحماض الكيتوني حتى مع سكر غير شديد الارتفاع.','eGFR، حجم السوائل، السكر وعلامات DKA/التهابات.','فوائده القلبية والكلوية ليست مجرد خفض للسكر.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Diabetes","SGLT2","Heart failure"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('pioglitazone','Pioglitazone','بيوغليتازون','A','Thiazolidinedione','PO',null,'Intermediate','السكري النوع 2 عند مرضى مختارين','ينشط PPAR-gamma ويزيد حساسية الإنسولين.','زيادة وزن، وذمة، خطر تفاقم قصور القلب وكسور.','غير مناسب في قصور القلب العرضي/الشديد وبعض الحالات؛ راجع المنتج.','قد يتأخر أثره أيامًا إلى أسابيع؛ أبلغ عن تورم أو ضيق نفس.','الوزن، الوذمة، السكر ووظائف الكبد حسب الخطة.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Diabetes","TZD"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('insulin-glargine','Insulin glargine','إنسولين غلارجين','A','Long-acting insulin','SC',null,'Intermediate','السكري النوع 1 والنوع 2 حسب النظام العلاجي','يعوض الإنسولين ويوفر تأثيرًا قاعديًا مستمرًا نسبيًا.','نقص السكر، زيادة وزن، نقص بوتاسيوم.','الحذر مع نوبات نقص السكر وتعديل الجرعة الفردي.','ثبات وقت الاستخدام بحسب المنتج، وتعلم قياس السكر ومواقع الحقن.','سكر الدم/HbA1c ونقص السكر.','ليس إنسولين وجبات؛ فرّق بين basal وprandial.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Insulin","Diabetes"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('insulin-lispro','Insulin lispro','إنسولين ليسبرو','A','Rapid-acting insulin','SC / Pump',null,'Intermediate','التحكم بالسكر حول الوجبات في أنظمة الإنسولين','نظير سريع للإنسولين يخفض الغلوكوز عبر زيادة دخوله للخلايا وتثبيط إنتاجه الكبدي.','نقص السكر، زيادة وزن، نقص بوتاسيوم.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','يرتبط بالوجبات؛ توقيت الجرعة مهم.','سكر الدم ونقص السكر.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Insulin","Prandial"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('liraglutide','Liraglutide','ليراغلوتايد','A','GLP-1 receptor agonist','SC',null,'Intermediate','السكري النوع 2، وفي بعض المرضى السمنة حسب الاستطباب والمنتج','ينشط GLP-1 ويزيد الإنسولين المعتمد على الغلوكوز ويقلل الغلوكاغون ويبطئ إفراغ المعدة.','غثيان، قيء، إسهال؛ مخاطر نادرة مثل التهاب البنكرياس.','موانع محددة حسب المنتج؛ الحذر في أمراض المرارة والجهاز الهضمي.','ابدأ وارفَع تدريجيًا وفق الخطة لتقليل الأعراض الهضمية.','الوزن، السكر، التحمل وأعراض البنكرياس/المرارة.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Diabetes","GLP-1"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('apixaban','Apixaban','أبيكسابان','B','Direct factor Xa inhibitor','PO',null,'Intermediate','منع السكتة في AF غير الصمامي وعلاج/وقاية VTE حسب الاستطباب','يثبط العامل Xa مباشرة فيقل توليد الثرومبين.','نزف، فقر دم، كدمات.','نزف نشط؛ الجرعة والملاءمة تتأثر بالعمر/الكلية/التداخلات حسب الاستطباب.','لا توقفه فجأة دون خطة؛ أخبر كل مقدم رعاية أنك تستخدمه.','علامات النزف ووظيفة الكلية والكبد وفق الحالة.','لا يحتاج INR روتينيًا مثل warfarin.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Anticoagulant","DOAC"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('rivaroxaban','Rivaroxaban','ريفاروكسابان','B','Direct factor Xa inhibitor','PO',null,'Intermediate','AF غير صمامي وVTE واستخدامات أخرى معتمدة','يثبط العامل Xa مباشرة.','نزف، فقر دم، أعراض هضمية.','نزف نشط؛ الانتباه لوظيفة الكلية والكبد والتداخلات.','بعض الجرعات تؤخذ مع الطعام حسب الاستطباب.','نزف، CBC ووظائف الكلى/الكبد حسب الحاجة.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Anticoagulant","DOAC"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('dabigatran','Dabigatran','دابيغاتران','B','Direct thrombin inhibitor','PO',null,'Intermediate','AF غير صمامي وعلاج/وقاية VTE في الاستطبابات المناسبة','يثبط الثرومبين مباشرة ويمنع تحويل الفيبرينوجين إلى فيبرين.','نزف، عسر هضم.','وظيفة الكلية مهمة؛ بعض الحالات والصمامات الميكانيكية ليست مناسبة.','تجنب فتح/سحق الكبسولة إلا إذا سمح المنتج؛ الحفظ والتعامل مهمان.','وظيفة الكلية وعلامات النزف.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Anticoagulant","DOAC"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('enoxaparin','Enoxaparin','إنوكسابارين','B','Low-molecular-weight heparin','SC',null,'Intermediate','وقاية/علاج VTE، وبعض ACS وفق البروتوكول','يعزز antithrombin ويثبط Xa بدرجة أكبر من IIa.','نزف، نقص صفائح مناعي مهم (HIT) نادر، فقر دم.','نزف نشط؛ الحذر في القصور الكلوي الشديد.','حقن تحت الجلد وتجنب تدليك موضع الحقن.','النزف، الصفائح ووظيفة الكلية في حالات مختارة.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["LMWH","VTE"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('aspirin','Aspirin','أسبرين','B','Antiplatelet / NSAID','PO',null,'Intermediate','منع الخثار الشرياني في استطبابات مختارة، ومسكن بجرعات أخرى','يثبط COX-1 في الصفائح بشكل غير عكوس ويقلل thromboxane A2.','نزف هضمي، كدمات، تشنج قصبي عند الحساسين.','نزف نشط وبعض الحساسية/القرحات؛ لا يستخدم للوقاية الأولية لكل شخص تلقائيًا.','لا تجمعه مع NSAIDs أو مضادات تخثر دون معرفة التداخل والخطة.','علامات النزف وضغط الدم/القرحة حسب المريض.','الجرعة والاستطباب يحددان إذا كان الهدف antiplatelet أو analgesic.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antiplatelet","COX"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ticagrelor','Ticagrelor','تيكاغريلور','B','P2Y12 inhibitor','PO',null,'Intermediate','ACS ومنع الأحداث الخثرية في الاستطبابات المناسبة','يثبط P2Y12 بشكل عكوس ويمنع تنشيط الصفائح.','نزف، ضيق نفس، بطء قلب في بعض المرضى.','نزف داخل القحف سابق/نزف فعال وبعض الموانع حسب المنتج.','لا توقفه ذاتيًا بعد PCI أو ACS.','نزف، ضيق النفس والالتزام والتداخلات.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antiplatelet","P2Y12"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('unfractionated-heparin','Unfractionated heparin','هيبارين غير مجزأ','B','Anticoagulant','IV / SC',null,'Intermediate','مضاد تخثر في المستشفى، ACS، VTE وبعض الإجراءات','يعزز antithrombin ويثبط thrombin وXa.','نزف، HIT، نقص صفائح.','نزف نشط وبعض اضطرابات التخثر.','يحتاج مراقبة مخبرية في الاستعمال الوريدي المعتاد.','aPTT/anti-Xa حسب البروتوكول، الصفائح والنزف.','سهل الإيقاف/العكس نسبيًا مقارنة ببعض الخيارات الطويلة.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Anticoagulant","Heparin"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('tranexamic-acid','Tranexamic acid','حمض الترانيكساميك','B','Antifibrinolytic','PO / IV / Topical',null,'Intermediate','تقليل النزف في حالات محددة مثل غزارة الطمث وبعض النزوف والإجراءات','يثبط تنشيط plasminogen إلى plasmin فيحد تحلل الفيبرين.','غثيان، صداع؛ خطر خثار في سياقات مختارة.','الحذر في تاريخ خثار/اختلال كلوي أو حالات محددة حسب الاستطباب.','ليس مناسبًا لكل نزف؛ السبب والمخاطر أهم.','النزف ووظائف الكلية وعلامات الخثار.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Hemostasis","Bleeding"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('epoetin-alfa','Epoetin alfa','إيبويتين ألفا','B','Erythropoiesis-stimulating agent','SC / IV',null,'Intermediate','فقر الدم المرتبط بأمراض مزمنة/كلوية وبعض علاجات السرطان وفق الاستطباب','ينشط مستقبل erythropoietin في نخاع العظم لزيادة إنتاج RBCs.','ارتفاع ضغط، خثار، زيادة Hb بسرعة.','هدف Hb فردي؛ خطر الأحداث القلبية/الخثرية مهم ولا يستخدم بلا تقييم.','قد يحتاج حديدًا كافيًا ومتابعة متقاربة.','Hb، ضغط الدم، الحديد والخطر الخثاري.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Anemia","Erythropoietin"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('cyanocobalamin','Cyanocobalamin','سيانوكوبالامين','B','Vitamin B12','PO / IM',null,'Intermediate','علاج نقص فيتامين B12 وبعض أنواع فقر الدم المرتبطة بالنقص','يعوض B12 الضروري لتكوين DNA ووظائف عصبية/دموية سليمة.','نادرًا طفح أو تفاعل تحسسي.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','الطريق والمدة يعتمدان على السبب والامتصاص.','CBC، B12 وأحيانًا MMA/homocysteine والاستجابة السريرية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["B12","Anemia"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('folic-acid','Folic acid','حمض الفوليك','B','Vitamin B9','PO',null,'Intermediate','علاج/وقاية نقص الفولات وبعض حالات الحمل وفق الإرشادات','يعوض الفولات الضروري لتصنيع DNA وكريات الدم.','عادة جيد التحمل؛ جرعات عالية قد تخفي نقص B12.','استبعاد نقص B12 قبل علاج فقر الدم طويل الأمد بالفولات وحده.','الحمل يحتاج جرعة محددة حسب الخطورة والإرشادات المحلية.','CBC والفولات/B12 حسب السبب.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Folate","Pregnancy"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('vitamin-k1','Vitamin K1','فيتامين K1','B','Vitamin K / hemostasis','PO / IV',null,'Intermediate','نقص فيتامين K وعكس تأثير warfarin في مواقف محددة','يعيد تدوير عوامل التخثر المعتمدة على فيتامين K.','تفاعلات موضعية/تحسس نادرًا؛ إعطاء IV يحتاج حذرًا.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','لا يستخدم لعكس warfarin إلا وفق شدة النزف/INR والبروتوكول.','INR والاستجابة للنزف.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Vitamin K","Warfarin reversal"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('lisinopril','Lisinopril','ليسينوبريل','C','ACE inhibitor','PO',null,'Intermediate','HTN، قصور القلب وبعض حالات CKD/البروتين في الاستطبابات المناسبة','يمنع ACE فيخفض angiotensin II وaldosterone.','سعال، ارتفاع K+، تدهور وظيفة الكلية؛ وذمة وعائية نادرة.','الحمل وموانع أخرى؛ الحذر في تضيق الشريان الكلوي.','أبلغ عن تورم الوجه/اللسان فورًا ولا تتناول مكملات البوتاسيوم دون استشارة.','ضغط الدم، K+ وcreatinine/eGFR.','ACEI قد يحمي الكلية في فئات مختارة رغم زيادة creatinine أوليًا.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('enalapril','Enalapril','إنالابريل','C','ACE inhibitor','PO / IV',null,'Intermediate','HTN وقصور القلب في الاستطبابات المناسبة','يتحول إلى enalaprilat ويثبط ACE.','سعال، ارتفاع K+، دوخة، وذمة وعائية نادرة.','','راقب ضغط الدم ووظائف الكلية.','الاستجابة والآثار الجانبية والعوامل الخاصة بالمريض.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('carvedilol','Carvedilol','كارفيديلول','C','Beta/alpha blocker','PO',null,'Intermediate','قصور القلب وHTN في مرضى مختارين','يحصر β وα1 فيقلل النبض والمقاومة الوعائية.','بطء قلب، انخفاض ضغط، تعب؛ تفاقم مؤقت لقصور القلب عند بدء العلاج بسرعة.','الحذر في الربو واضطرابات التوصيل؛ لا يوقف فجأة.','يُزاد تدريجيًا في قصور القلب حسب الخطة.','نبض، ضغط، وزن وأعراض قصور القلب.','الـtitration مهم أكثر من الجرعة الابتدائية.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('bisoprolol','Bisoprolol','بيسوبرولول','C','Beta1-selective blocker','PO',null,'Intermediate','HTN، الذبحة، قصور القلب في مرضى مختارين','يحصر β1 ويخفض معدل القلب والقوة وإفراز الرينين.','بطء قلب، تعب، دوخة.','الحذر في الربو/heart block؛ لا يوقف فجأة.','راقب النبض والضغط.','نبض، ضغط وأعراض قصور القلب.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('metoprolol','Metoprolol','ميتوبرولول','C','Beta1-selective blocker','PO / IV',null,'Intermediate','HTN، angina، بعض اضطرابات النظم وقصور القلب حسب الصيغة','يحصر β1 القلبي.','بطء قلب، تعب، دوخة.','الحذر في الربو واضطرابات التوصيل؛ الصيغة ER ليست مثل IR.','لا توقف فجأة.','نبض وضغط وأعراض.','صيغة tartrate تختلف عن succinate في الاستخدامات.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('spironolactone','Spironolactone','سبيرونولاكتون','C','Mineralocorticoid receptor antagonist','PO',null,'Intermediate','قصور القلب، فرط الألدوستيرون، وبعض حالات HTN/الوذمة','يمنع مستقبل الألدوستيرون ويحتفظ بالبوتاسيوم.','فرط K+، تثدي، اضطرابات طمث.','فرط K+ وقصور الكلية مهمان؛ لا يجمع عشوائيًا مع أدوية ترفع K+.','تجنب مكملات البوتاسيوم دون إشراف.','K+ وcreatinine وضغط الدم.','حافظ البوتاسيوم مقابل loop diuretics.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('hydrochlorothiazide','Hydrochlorothiazide','هيدروكلوروثيازيد','C','Thiazide diuretic','PO',null,'Intermediate','HTN ووذمة في حالات محددة','يثبط NCC في النبيب الملتوي البعيد ويزيد طرح الصوديوم.','نقص Na/K، فرط حمض البول، زيادة سكر، جفاف.','الحذر في النقرس/اختلال الشوارد.','اشرب حسب الخطة؛ راقب الدوخة.','BP، Na/K وuric acid/glucose عند الحاجة.','فعاليته تعتمد على وظيفة الكلية والحالة.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('chlorthalidone','Chlorthalidone','كلورثاليدون','C','Thiazide-like diuretic','PO',null,'Intermediate','HTN ووذمة في المرضى المناسبين','يثبط ناقل Na/Cl في الـDCT ويزيد natriuresis.','نقص K/Na، دوخة، فرط حمض البول.','','المراقبة المخبرية مهمة خصوصًا بعد البدء/رفع الجرعة.','BP وelectrolytes.','نصف عمر أطول من HCTZ.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('valsartan','Valsartan','فالسارتان','C','ARB','PO',null,'Intermediate','HTN، قصور القلب، وبعض أمراض القلب','يحصر AT1 فيقلل تأثير angiotensin II.','دوخة، فرط K، تغير renal function.','الحمل وموانع أخرى حسب الحالة.','لا تستخدم K supplements دون استشارة.','BP، K، creatinine.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('sacubitril-valsartan','Sacubitril/valsartan','ساكوبيتريل/فالسارتان','C','ARNI','PO',null,'Intermediate','قصور القلب المزمن في المرضى المناسبين','sacubitril يزيد natriuretic peptides عبر تثبيط neprilysin وvalsartan يحصر AT1.','هبوط ضغط، فرط K، تغير renal function، وذمة وعائية.','يتطلب الانتباه لفاصل زمني بعد ACE inhibitor بسبب خطر الوذمة الوعائية.','لا تبدأه مباشرة بعد ACEI دون الفاصل الموصى به.','BP، K، creatinine.','من العلاجات الأساسية الحديثة في HFrEF عند الملاءمة.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('nitroglycerin','Nitroglycerin','نيتروغليسرين','C','Organic nitrate','SL / IV / Topical',null,'Intermediate','تخفيف الذبحة وعلاج بعض الحالات الإسعافية القلبية تحت بروتوكول','يطلق NO فيسبب توسعًا وريديًا وشريانيًا.','صداع، احمرار، هبوط ضغط، تسرع انعكاسي.','ممنوع مع PDE5 inhibitors وفي حالات هبوط ضغط معينة.','اجلس عند استعمال SL وتجنب أدوية ضعف الانتصاب المتعارضة.','ضغط الدم، ألم الصدر والاستجابة.','التحمل قد يحدث مع الاستخدام المستمر لبعض الصيغ.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('isosorbide-mononitrate','Isosorbide mononitrate','إيزوسوربيد مونونترات','C','Organic nitrate','PO',null,'Intermediate','الوقاية من الذبحة وليس الإغاثة الفورية','موسّع وعائي عبر NO.','صداع، دوخة، انخفاض ضغط.','ممنوع مع PDE5 inhibitors.','اتباع فترة خالية من النترات حسب الصيغة لمنع tolerance.','BP والأعراض.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('diltiazem','Diltiazem','ديلتيازيم','C','Non-dihydropyridine CCB','PO / IV',null,'Intermediate','AF rate control، angina وHTN في سياقات مختارة','يحصر L-type calcium channels ويبطئ AV node ويقلل contractility.','بطء قلب، وذمة، إمساك، انخفاض ضغط.','حذر في HFrEF واضطرابات التوصيل؛ تداخلات CYP3A4.','لا تسحق ER forms.','HR/BP وECG في الاستخدامات المناسبة.','Cardioselective but not beta blocker.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('verapamil','Verapamil','فيراباميل','C','Non-dihydropyridine CCB','PO / IV',null,'Intermediate','SVT/AF rate control وبعض أنواع الذبحة/HTN','يقلل توصيل AV ويخفض contractility.','إمساك، بطء قلب، انخفاض ضغط.','حذر في HFrEF وheart block؛ تداخلات دوائية متعددة.','انتبه للإمساك والتداخلات.','HR/BP/ECG.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('amiodarone','Amiodarone','أميودارون','C','Class III antiarrhythmic','PO / IV',null,'Intermediate','اضطرابات نظم خطيرة في استطبابات محددة','يطيل repolarization ويؤثر في عدة قنوات ومستقبلات.','أمراض درقية، كبدية، رئوية، QT prolongation، تفاعلات جلدية/عينية.','مراقبة واسعة مطلوبة؛ تداخلات كثيرة.','لا تبدأ/تعدل دون خطة متابعة.','ECG، TSH، LFTs، رئة وعين حسب المدة.','نصف عمر طويل جدًا وتداخلات كثيرة.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('digoxin','Digoxin','ديجوكسين','C','Cardiac glycoside','PO / IV',null,'Intermediate','قصور القلب وAF rate control في مرضى مختارين','يثبط Na/K ATPase ويرفع Ca داخل الخلية، ويزيد vagal tone.','غثيان، اضطرابات رؤية، بطء/اضطراب نظم؛ سمية خطيرة في نقص K/قصور الكلية.','جرعة فردية دقيقة، تداخلات متعددة.','تجنب التغييرات المفاجئة في K والسوائل دون متابعة.','وظيفة الكلية، K، ECG ومستوى الدواء عند الحاجة.','مؤشر علاجي ضيق.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('rosuvastatin','Rosuvastatin','روسوفاستاتين','C','Statin','PO',null,'Intermediate','خفض LDL وتقليل الخطر القلبي الوعائي','يثبط HMG-CoA reductase ويزيد LDL receptor expression.','ألم عضلي، ارتفاع LFTs، اعتلال عضلي نادر.','الحمل وبعض الحالات/التداخلات.','أبلغ عن ألم عضلي شديد.','lipid panel والأعراض وLFTs عند الحاجة.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ezetimibe','Ezetimibe','إيزيتيميب','C','Cholesterol absorption inhibitor','PO',null,'Intermediate','خفض LDL بمفرده أو مع statin','يثبط NPC1L1 ويقلل امتصاص الكوليسترول المعوي.','إسهال، ألم عضلي عند المشاركة، ارتفاع LFT مع statin.','','يُستخدم غالبًا كإضافة عندما لا يكفي statin أو لا يُحتمل.','Lipids وLFTs بحسب المشاركة.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('gemfibrozil','Gemfibrozil','جيمفيبروزيل','C','Fibrate','PO',null,'Intermediate','ارتفاع triglycerides في حالات مختارة','ينشط PPAR-alpha ويغير استقلاب الدهون.','GI upset، حصى مرارية، myopathy.','تداخل مهم مع بعض statins؛ تجنب الجمع غير الضروري.','أبلغ عن ألم عضلي شديد.','TG، LFTs وCK عند الأعراض.','انتبه لتداخلاته مع statins.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('clonidine','Clonidine','كلونيدين','C','Central alpha2 agonist','PO / Patch',null,'Intermediate','HTN في حالات مختارة','يقلل النشاط الودي المركزي عبر α2.','نعاس، جفاف فم، بطء قلب؛ rebound hypertension عند الإيقاف المفاجئ.','لا توقف فجأة دون خطة.','الالتزام مهم جدًا لأن الانقطاع المفاجئ قد يرفع الضغط.','BP وHR.','ليس خيارًا أوليًا في كثير من الحالات المزمنة.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cardiovascular"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('hydrocortisone-topical','Hydrocortisone topical','هيدروكورتيزون موضعي','D','Topical corticosteroid','Topical',null,'Intermediate','التهاب الجلد الخفيف والحكة في استطبابات مناسبة','ينشط glucocorticoid receptor ويقلل الالتهاب الموضعي.','ترقق الجلد، تهيج؛ امتصاص جهازي مع الاستخدام الواسع/الطويل.','تجنب العين والجروح والعدوى غير المعالجة؛ القوة والمدة مهمتان.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Eczema","Steroid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('betamethasone-topical','Betamethasone topical','بيتاميثازون موضعي','D','Topical corticosteroid','Topical',null,'Intermediate','التهابات جلدية تستجيب للستيرويد حسب القوة والموقع','يثبط mediators الالتهاب عبر glucocorticoid receptor.','ترقق الجلد، striae، امتصاص جهازي عند الاستخدام المكثف.','الحذر في الوجه والثنيات والعدوى.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Eczema","Steroid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('mometasone','Mometasone','موميتازون','D','Topical corticosteroid','Topical',null,'Intermediate','الأكزيما والتهاب الجلد والحكة في حالات مناسبة','مضاد للالتهاب ومثبط للمناعة موضعيًا.','ضمور جلد وتهيج عند الإفراط.','لا تستخدم لعدوى فطرية غير معالجة أو لفترات طويلة بلا مراجعة.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Eczema","Steroid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('clobetasol','Clobetasol','كلوبيتازول','D','Very potent topical corticosteroid','Topical',null,'Intermediate','أمراض جلدية شديدة الحساسية للستيرويد لفترة محدودة','ستيرويد موضعي شديد القوة يقلل الالتهاب.','ضمور الجلد، توسعات وعائية، تثبيط محوري مع الاستخدام الواسع.','مدة قصيرة ومناطق محدودة إلا تحت إشراف مختص.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Psoriasis","Steroid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('tacrolimus-ointment','Tacrolimus ointment','تاكروليمس مرهم','D','Topical calcineurin inhibitor','Topical',null,'Intermediate','التهاب الجلد التأتبي في مواقع/مرضى مختارين','يثبط calcineurin ويقلل تنشيط T cells وإنتاج السيتوكينات.','حرقان موضعي، احمرار؛ حساسية للشمس.','لا يستخدم على عدوى نشطة دون تقييم.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Atopic dermatitis"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('mupirocin','Mupirocin','موبيروسين','D','Topical antibiotic','Topical',null,'Intermediate','عدوى جلدية بكتيرية سطحية محددة','يثبط isoleucyl-tRNA synthetase في البكتيريا.','تهيج موضعي، تحسس نادر.','استخدامه عشوائيًا يزيد مقاومة المضادات.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Bacterial skin infection"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('fusidic-acid','Fusidic acid','حمض الفيوسيديك','D','Topical antibiotic','Topical',null,'Intermediate','عدوى جلدية بكتيرية محددة حسب المقاومة المحلية','يثبط elongation factor G ويوقف تصنيع البروتين البكتيري.','تهيج جلدي وتحسس.','المقاومة مهمة؛ تجنب الاستخدام الطويل غير المبرر.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Bacterial skin infection"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('clindamycin-topical','Clindamycin topical','كليندامايسين موضعي','D','Topical lincosamide','Topical',null,'Intermediate','حب الشباب وبعض العدوى الجلدية وفق الاستطباب','يثبط 50S ribosomal subunit ويوقف تصنيع البروتين.','جفاف وتهيج؛ نادرًا التهاب قولون مرتبط بالمضاد.','يفضل غالبًا دمجه في حب الشباب مع benzoyl peroxide لتقليل المقاومة.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Acne"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('benzoyl-peroxide','Benzoyl peroxide','بنزويل بيروكسيد','D','Topical acne therapy','Topical',null,'Intermediate','حب الشباب الخفيف إلى المتوسط','له تأثير مؤكسد مضاد للبكتيريا ويفتح الكوميدونات.','جفاف وتهيج وتفتيح الأقمشة.','ابدأ تدريجيًا لتقليل التهيج.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Acne"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('adapalene','Adapalene','أدابالين','D','Topical retinoid','Topical',null,'Intermediate','حب الشباب الكوميدوني/الالتهابي','ينظم تمايز الخلايا الكيراتينية عبر retinoid receptors.','جفاف، احمرار، حساسية للشمس.','الحمل يحتاج تقييمًا وتوصيات مناسبة؛ ليس كل retinoids متساوية.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Acne","Retinoid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('tretinoin-topical','Tretinoin topical','تريتينوين موضعي','D','Topical retinoid','Topical',null,'Intermediate','حب الشباب وبعض الاستخدامات الجلدية','ينظم transcription عبر retinoic acid receptors ويمنع انسداد الجريبات.','تهيج وتقشر وحساسية للشمس.','يحتاج حماية من الشمس وتدرجًا في الاستخدام.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Acne","Retinoid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ketoconazole-cream','Ketoconazole cream','كيتوكونازول كريم','D','Topical azole antifungal','Topical',null,'Intermediate','tinea وبعض داء المبيضات/الالتهابات الفطرية السطحية','يثبط ergosterol synthesis عبر 14-alpha demethylase.','تهيج وحرقان.','التشخيص الصحيح للعدوى مهم.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Fungal skin infection"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('terbinafine-cream','Terbinafine cream','تيربينافين كريم','D','Topical allylamine antifungal','Topical',null,'Intermediate','tinea الجلدية والقدم الرياضي في الاستطبابات المناسبة','يثبط squalene epoxidase ويؤدي لنقص ergosterol وتراكم squalene.','تهيج موضعي.','لا تستخدمه لكل طفح غير مشخص.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Tinea"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('calamine','Calamine','كالامين','D','Protective antipruritic','Topical',null,'Intermediate','حكة وتهيج جلدي بسيط','يعمل كمجفف وطبقة واقية ومهدئة موضعية.','جفاف أو تهيج خفيف.','تجنب العين والجروح.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Pruritus"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('salicylic-acid-topical','Salicylic acid topical','حمض الساليسيليك موضعي','D','Keratolytic','Topical',null,'Intermediate','فرط التقرن والثآليل وحب الشباب بحسب التركيز','يفكك الروابط بين خلايا الطبقة القرنية ويقلل الانسداد.','تهيج وحرقان؛ سمية جهازية عند الاستخدام الواسع بتركيزات عالية.','التركيز والمنطقة مهمان؛ الحذر عند الأطفال والمساحات الكبيرة.','استخدم طبقة رقيقة بالكمية والمدة الموصى بهما؛ تجنب العين ومواطن الالتهاب الشديد.','راقب التحسن، التهيج وظهور علامات عدوى أو حساسية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Keratolytic"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('finasteride','Finasteride','فيناستيرايد','G','5-alpha reductase inhibitor','PO',null,'Intermediate','BPH وبعض أنماط تساقط الشعر','يقلل تحويل testosterone إلى DHT.','انخفاض الرغبة الجنسية، اضطراب الانتصاب/القذف.','لا يُلمس من قبل الحوامل شكل الأقراص المكسورة؛ تأثيره يحتاج أشهر.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["BPH","Hair loss"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('oxybutynin','Oxybutynin','أوكسيبوتينين','G','Antimuscarinic','PO / Patch',null,'Intermediate','فرط نشاط المثانة','يحصر muscarinic receptors ويقلل تقلص detrusor.','جفاف الفم، إمساك، تشوش رؤية، احتباس بول.','الحذر في glaucoma وretention.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Overactive bladder"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('mirabegron','Mirabegron','ميرابيغرون','G','Beta3 agonist','PO',null,'Intermediate','فرط نشاط المثانة','ينشط β3 في المثانة ويرخي detrusor أثناء الامتلاء.','ارتفاع ضغط، صداع، تسرع قلب.','الحذر في HTN غير المضبوط وتداخلات CYP2D6.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Overactive bladder"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('tadalafil','Tadalafil','تادالافيل','G','PDE5 inhibitor','PO',null,'Intermediate','ضعف الانتصاب وBPH وPAH حسب الاستطباب','يثبط PDE5 ويزيد cGMP.','صداع، ألم ظهر، عسر هضم، هبوط ضغط مع nitrates.','ممنوع مع nitrates؛ عمر تأثير أطول من sildenafil.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["ED","BPH"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('levonorgestrel-emergency','Levonorgestrel emergency','ليفونورجيستريل للطوارئ','G','Emergency contraceptive progestin','PO',null,'Intermediate','منع الحمل الطارئ في حالات محددة','يؤخر/يمنع الإباضة أساسًا.','غثيان، صداع، تغير نزف الدورة.','لا يُستخدم كوسيلة منتظمة؛ النجاعة تتأثر بالوقت وبعض الأدوية/الوزن.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Contraception"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ethinyl-estradiol-levonorgestrel','Ethinyl estradiol / levonorgestrel','إيثينيل إستراديول / ليفونورجيستريل','G','Combined oral contraceptive','PO',null,'Intermediate','منع الحمل وتنظيم الدورة وبعض الاستطبابات الهرمونية','يمنع الإباضة ويغير مخاط عنق الرحم وبطانة الرحم.','غثيان، نزف غير منتظم، ارتفاع ضغط؛ خطر VTE في فئات مختارة.','ممنوعات كثيرة خصوصًا التدخين مع العمر/الخثار/الشقيقة مع aura.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Contraception"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('estradiol','Estradiol','إستراديول','G','Estrogen','PO / Transdermal / Other',null,'Intermediate','أعراض نقص الإستروجين وبعض العلاجات الهرمونية','ينشط estrogen receptors ويغير نسخ الجينات المستجيبة للإستروجين.','نزف، ألم ثدي، غثيان؛ مخاطر خثار/بطانة الرحم حسب الصيغة.','التقييم الفردي للخثار والسرطان ضروري.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["HRT"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('progesterone','Progesterone','بروجستيرون','G','Progestogen','PO / Other',null,'Intermediate','HRT وبعض اضطرابات النزف/الخصوبة حسب المنتج','يعمل عبر progesterone receptor لتعديل بطانة الرحم ووظائف تناسلية.','نعاس، انتفاخ، تغيرات مزاجية.','الصيغة والاستطباب يحددان الموانع.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["HRT"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('desmopressin','Desmopressin','ديسموبريسين','G','Vasopressin analog','PO / IN / Injectable',null,'Intermediate','Diabetes insipidus وبعض حالات enuresis/hemophilia/vWD وفق المنتج','نظير ADH يزيد إعادة امتصاص الماء، ويزيد vWF/FVIII بجرعات محددة.','نقص صوديوم خطير، صداع واحتباس سوائل.','تقييد السوائل مهم حسب الاستخدام.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Diabetes insipidus","Hyponatremia"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('methimazole','Methimazole','ميثيمازول','H','Antithyroid thionamide','PO',null,'Intermediate','فرط الدرق','يثبط thyroid peroxidase ويقلل تصنيع هرمونات الدرق.','طفح؛ agranulocytosis والتهاب كبد نادران لكن مهمان.','الحمل ومراحل الحمل تحتاج اختيارًا مدروسًا.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Hyperthyroidism"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('propylthiouracil','Propylthiouracil','بروبيل ثيوراسيل','H','Antithyroid thionamide','PO',null,'Intermediate','فرط الدرق في مواقف مختارة وعاصفة درقية وفق البروتوكول','يثبط thyroid peroxidase ويقلل تحويل T4 إلى T3 محيطيًا.','سمية كبدية شديدة، agranulocytosis.','عادة ليس الخيار الأول طويل الأمد خارج مواقف محددة.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Hyperthyroidism"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('dexamethasone','Dexamethasone','ديكساميثازون','H','Systemic corticosteroid','PO / IV / IM',null,'Intermediate','وذمة دماغية وبعض الحالات الالتهابية/السرطانية والـantiemetic protocols حسب الاستطباب','غلوكوكورتيكويد قوي طويل المفعول.','ارتفاع سكر، عدوى، اضطرابات مزاج ونوم، ضعف عضلي.','المتابعة والتدرج مهمان في الاستعمال المطول.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Steroid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('calcitriol','Calcitriol','كالسيتريول','H','Active vitamin D analog','PO',null,'Intermediate','اضطرابات استقلاب الكالسيوم/الفوسفور وحالات كلوية مختارة','يرتبط بمستقبل vitamin D ويزيد امتصاص Ca/P.','فرط كالسيوم الدم، فرط فوسفور الدم.','مراقبة الكالسيوم والفوسفور ضرورية.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Bone metabolism"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('cabergoline','Cabergoline','كابيرغولين','H','Dopamine agonist','PO',null,'Intermediate','فرط البرولاكتين وبعض اضطرابات النخامى','ينشط D2 ويثبط إفراز prolactin.','غثيان، دوخة، انخفاض ضغط؛ مشاكل صمامات مع جرعات مزمنة عالية.','الحمل والمرض القلبي يحتاجان تقييمًا.','اتبع الجرعة والتوقيت بدقة؛ بعض هذه الأدوية تحتاج تدرجًا ومتابعة مخبرية.','المؤشرات الحيوية/التحاليل المرتبطة بالاستطباب والآثار الجانبية.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Hyperprolactinemia"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('amoxicillin-clavulanate','Amoxicillin/clavulanate','أموكسيسيلين/كلافولانات','J','Penicillin + beta-lactamase inhibitor','PO / IV',null,'Intermediate','عدوى بكتيرية حساسة مع احتمال إنتاج beta-lactamase','amoxicillin يثبط PBPs وclavulanate يثبط بعض beta-lactamases.','إسهال، غثيان، التهاب كبد دوائي نادر.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antibiotic","Beta-lactamase"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('cephalexin','Cephalexin','سيفاليكسين','J','First-generation cephalosporin','PO',null,'Intermediate','جلدية/بولية وبعض العدوى الحساسة','يثبط تصنيع جدار الخلية عبر PBPs.','إسهال، طفح، تحسس.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cephalosporin"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ceftriaxone','Ceftriaxone','سيفترياكسون','J','Third-generation cephalosporin','IM / IV',null,'Intermediate','عدوى بكتيرية شائعة شديدة حسب الاستطباب','يثبط PBPs ويمنع بناء الجدار.','إسهال، طفح؛ biliary sludging نادر.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cephalosporin"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('cefepime','Cefepime','سيفيبيم','J','Fourth-generation cephalosporin','IV',null,'Intermediate','عدوى شديدة/مستشفوية حساسة','يثبط PBPs ويتميز بنشاط واسع نسبيًا ضد Gram-negatives.','تحسس، إسهال؛ neurotoxicity في القصور الكلوي.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cephalosporin","Hospital"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('piperacillin-tazobactam','Piperacillin/tazobactam','بيبيراسيلين/تازوباكتام','J','Antipseudomonal penicillin + inhibitor','IV',null,'Intermediate','عدوى شديدة متعددة الميكروبات حسب البروتوكول','piperacillin يثبط PBPs وtazobactam يثبط beta-lactamases.','إسهال، تحسس، اضطراب شوارد، تدهور كلوي مع بعض المشاركات.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Hospital","Antipseudomonal"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('clarithromycin','Clarithromycin','كلاريثروميسين','J','Macrolide','PO',null,'Intermediate','عدوى تنفسية وبعض نظم H. pylori/عدوى أخرى','يرتبط بالـ50S ويثبط تصنيع البروتين.','اضطراب تذوق، GI، QT، تداخلات CYP3A4.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Macrolide","CYP3A4"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('doxycycline','Doxycycline','دوكسيسيكلين','J','Tetracycline','PO / IV',null,'Intermediate','التهابات بكتيرية متعددة مثل atypical/rickettsial/acne','يرتبط بالـ30S ويمنع إضافة aminoacyl-tRNA.','غثيان، photosensitivity، التهاب مريء.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Tetracycline"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ciprofloxacin','Ciprofloxacin','سيبروفلوكساسين','J','Fluoroquinolone','PO / IV',null,'Intermediate','عدوى بكتيرية محددة وفق المقاومة المحلية','يثبط DNA gyrase وtopoisomerase IV.','اعتلال أوتار، QT، تأثيرات CNS؛ C. difficile.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Fluoroquinolone"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('levofloxacin','Levofloxacin','ليفوفلوكساسين','J','Fluoroquinolone','PO / IV',null,'Intermediate','عدوى بكتيرية محددة','يثبط DNA gyrase/topoisomerase IV.','أوتار، QT، CNS، dysglycemia؛ C. difficile.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Fluoroquinolone"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('metronidazole','Metronidazole','ميترونيدازول','J','Nitroimidazole','PO / IV / Topical',null,'Intermediate','عدوى anaerobes وبعض الطفيليات','يُختزل داخل الكائنات الحساسة ويؤذي DNA.','غثيان، طعم معدني، neuropathy مع الاستعمال المطول؛ disulfiram-like reaction مع الكحول وفق المراجع.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Anaerobes","Protozoa"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('clindamycin','Clindamycin','كليندامايسين','J','Lincosamide','PO / IV',null,'Intermediate','عدوى موجبة الغرام/anaerobes في مواقف محددة','يثبط 50S ويمنع تصنيع البروتين.','إسهال وC. difficile مهم.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Anaerobes"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('vancomycin','Vancomycin','فانكوميسين','J','Glycopeptide antibiotic','IV / PO',null,'Intermediate','عدوى Gram-positive شديدة، وPO في C. difficile','يثبط بناء جدار الخلية عبر الارتباط بـD-Ala-D-Ala.','Nephrotoxicity، infusion reaction؛ ototoxicity نادر.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["MRSA","Glycopeptide"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('gentamicin','Gentamicin','جنتاميسين','J','Aminoglycoside','IV / IM',null,'Intermediate','عدوى Gram-negative شديدة ضمن مشاركات محددة','يرتبط 30S ويسبب أخطاء في قراءة mRNA ويثبط البدء.','Nephrotoxicity، ototoxicity، neuromuscular blockade.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Aminoglycoside"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('oseltamivir','Oseltamivir','أوسيلتاميفير','J','Neuraminidase inhibitor','PO',null,'Intermediate','الإنفلونزا في المرضى المناسبين وبالوقت المناسب','يثبط neuraminidase ويقلل خروج الفيروس من الخلايا المصابة.','غثيان وقيء؛ أحداث عصبية نادرة.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Influenza","Antiviral"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('rifampin','Rifampin','ريفامبين','J','Rifamycin antibiotic','PO / IV',null,'Intermediate','السل وممرضات أخرى في نظم محددة','يثبط DNA-dependent RNA polymerase البكتيري.','سمية كبد، تداخلات قوية، تغير لون الإفرازات إلى البرتقالي.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["TB","Rifamycin"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('isoniazid','Isoniazid','إيزونيازيد','J','Antitubercular','PO / IM',null,'Intermediate','علاج السل ضمن نظم متعددة الأدوية','يثبط تصنيع mycolic acids بعد تفعيله داخل المتفطرات.','سمية كبدية، peripheral neuropathy.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["TB"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ethambutol','Ethambutol','إيثامبوتول','J','Antitubercular','PO',null,'Intermediate','السل ضمن نظم متعددة الأدوية','يثبط arabinosyl transferases ويؤثر في جدار المتفطرة.','optic neuritis واضطراب رؤية الألوان، فرط حمض البول.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["TB"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('pyrazinamide','Pyrazinamide','بيرازيناميد','J','Antitubercular','PO',null,'Intermediate','السل في المرحلة المكثفة من النظم','يتحول إلى pyrazinoic acid ويؤثر في استقلاب المتفطرات.','سمية كبدية وفرط حمض البول.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["TB"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('nitrofurantoin','Nitrofurantoin','نيتروفورانتوين','J','Urinary antibacterial','PO',null,'Intermediate','التهاب المسالك البولية السفلي غير المعقد عند الملاءمة','يتحول إلى نواتج تفاعلية تؤذي DNA والبروتينات البكتيرية.','غثيان، تغير لون البول، سمية رئوية/كبدية نادرة؛ neuropathy.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','استخدم المضاد فقط عند الاستطباب، أكمل الخطة كما وُصفت ولا تشارك المضاد مع غيرك.','الاستجابة، الحساسية، وظائف الكلى/الكبد عند الحاجة، وعلامات C. difficile.','اختيار المضاد يجب أن يراعي الموقع الجرثومي، المقاومة المحلية، الحساسية ووظائف الأعضاء.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["UTI"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('methotrexate','Methotrexate','ميثوتركسات','L','Antimetabolite / immunomodulator','PO / SC / IM / IV',null,'Intermediate','أمراض مناعية محددة وبعض الأورام','يثبط dihydrofolate reductase بجرعات علاجية معينة ويعدل adenosine pathways في الأمراض الالتهابية.','تثبيط نخاع، سمية كبد، تقرحات فموية، teratogenicity.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','هذه أدوية عالية الخطورة نسبيًا وتحتاج بروتوكولًا ومراقبة اختصاصية؛ لا تُستخدم ذاتيًا.','CBC، وظائف أعضاء محددة، والتأثيرات الخاصة بالدواء والبروتوكول.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Rheumatology","Oncology"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('hydroxychloroquine','Hydroxychloroquine','هيدروكسي كلوروكوين','L','Antimalarial / immunomodulator','PO',null,'Intermediate','بعض أمراض المناعة الذاتية مثل SLE/RA، ولحالات malaria محددة','يتراكم داخل lysosomes ويغير antigen processing ومسارات إشارات مناعية.','retinopathy، QT prolongation، GI upset.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','هذه أدوية عالية الخطورة نسبيًا وتحتاج بروتوكولًا ومراقبة اختصاصية؛ لا تُستخدم ذاتيًا.','CBC، وظائف أعضاء محددة، والتأثيرات الخاصة بالدواء والبروتوكول.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["SLE","RA"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('tamoxifen','Tamoxifen','تاموكسيفين','L','Selective estrogen receptor modulator','PO',null,'Intermediate','سرطان الثدي الإيجابي لمستقبل الإستروجين في سياقات محددة','يعمل كمضاد للإستروجين في نسيج الثدي وله تأثيرات مختلفة حسب النسيج.','Hot flashes، زيادة خطر VTE وسرطان بطانة الرحم.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','هذه أدوية عالية الخطورة نسبيًا وتحتاج بروتوكولًا ومراقبة اختصاصية؛ لا تُستخدم ذاتيًا.','CBC، وظائف أعضاء محددة، والتأثيرات الخاصة بالدواء والبروتوكول.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Breast cancer"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('anastrozole','Anastrozole','أناستروزول','L','Aromatase inhibitor','PO',null,'Intermediate','سرطان الثدي بعد سن اليأس في الحالات المناسبة','يثبط aromatase ويقلل تصنيع الإستروجين المحيطي.','آلام مفاصل، فقدان عظم، hot flashes.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','هذه أدوية عالية الخطورة نسبيًا وتحتاج بروتوكولًا ومراقبة اختصاصية؛ لا تُستخدم ذاتيًا.','CBC، وظائف أعضاء محددة، والتأثيرات الخاصة بالدواء والبروتوكول.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Breast cancer"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('imatinib','Imatinib','إيماتينيب','L','Tyrosine kinase inhibitor','PO',null,'Intermediate','CML وبعض الأورام النسيجية ذات طفرات محددة','يثبط BCR-ABL وc-KIT وPDGFR وغيرها.','وذمة، غثيان، تثبيط نخاع، سمية كبدية.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','هذه أدوية عالية الخطورة نسبيًا وتحتاج بروتوكولًا ومراقبة اختصاصية؛ لا تُستخدم ذاتيًا.','CBC، وظائف أعضاء محددة، والتأثيرات الخاصة بالدواء والبروتوكول.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["CML","TKI"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('rituximab','Rituximab','ريتوكسيماب','L','Anti-CD20 monoclonal antibody','IV',null,'Intermediate','أورام دموية وبعض أمراض المناعة الذاتية','يرتبط CD20 ويؤدي إلى استنزاف B cells.','Infusion reactions، عدوى، HBV reactivation، PML نادر.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','هذه أدوية عالية الخطورة نسبيًا وتحتاج بروتوكولًا ومراقبة اختصاصية؛ لا تُستخدم ذاتيًا.','CBC، وظائف أعضاء محددة، والتأثيرات الخاصة بالدواء والبروتوكول.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Monoclonal antibody","CD20"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('trastuzumab','Trastuzumab','تراستوزوماب','L','Anti-HER2 monoclonal antibody','IV / SC',null,'Intermediate','سرطانات HER2-positive محددة','يرتبط HER2 ويثبط إشاراته المناعية/النموية.','Cardiomyopathy، infusion reaction.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','هذه أدوية عالية الخطورة نسبيًا وتحتاج بروتوكولًا ومراقبة اختصاصية؛ لا تُستخدم ذاتيًا.','CBC، وظائف أعضاء محددة، والتأثيرات الخاصة بالدواء والبروتوكول.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["HER2","Breast cancer"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('cyclophosphamide','Cyclophosphamide','سيكلوفوسفاميد','L','Alkylating agent','PO / IV',null,'Intermediate','أورام وأمراض مناعة ذاتية شديدة في بروتوكولات محددة','يضيف مجموعات ألكيلية إلى DNA ويمنع انقسام الخلايا.','تثبيط نخاع، عقم، hemorrhagic cystitis، secondary malignancy.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','هذه أدوية عالية الخطورة نسبيًا وتحتاج بروتوكولًا ومراقبة اختصاصية؛ لا تُستخدم ذاتيًا.','CBC، وظائف أعضاء محددة، والتأثيرات الخاصة بالدواء والبروتوكول.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Chemotherapy","Immunosuppression"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('naproxen','Naproxen','نابروكسين','M','NSAID','PO',null,'Intermediate','الألم/الالتهاب/عسر الطمث وبعض الحالات المفصلية','يثبط COX ويقلل prostaglandins.','GI bleeding، renal injury، fluid retention.','مراعاة وظيفة الكلية/الكبد وخطر النزف أو التداخلات حسب الدواء.','تجنب الجمع العشوائي بين NSAIDs، وانتبه لوظائف الكلية والجهاز الهضمي وأمراض القلب.','الألم/الالتهاب، ضغط الدم، وظائف الكلية والآثار الخاصة بالدواء.','اختيار NSAID يعتمد على المريض والمخاطر أكثر من كونه “أقوى مسكن”.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["NSAID"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('diclofenac','Diclofenac','ديكلوفيناك','M','NSAID','PO / Topical / IM / Other',null,'Intermediate','الألم والالتهاب، مع اختلاف الاستطباب حسب الصيغة','يثبط COX ويقلل prostaglandins.','GI toxicity، renal effects، cardiovascular risk.','مراعاة وظيفة الكلية/الكبد وخطر النزف أو التداخلات حسب الدواء.','تجنب الجمع العشوائي بين NSAIDs، وانتبه لوظائف الكلية والجهاز الهضمي وأمراض القلب.','الألم/الالتهاب، ضغط الدم، وظائف الكلية والآثار الخاصة بالدواء.','اختيار NSAID يعتمد على المريض والمخاطر أكثر من كونه “أقوى مسكن”.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["NSAID"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('celecoxib','Celecoxib','سيليكوكسيب','M','Selective COX-2 inhibitor','PO',null,'Intermediate','ألم/التهاب مفصلي في المرضى المناسبين','يثبط COX-2 أكثر من COX-1.','CV risk، edema، renal/GI effects.','مراعاة وظيفة الكلية/الكبد وخطر النزف أو التداخلات حسب الدواء.','تجنب الجمع العشوائي بين NSAIDs، وانتبه لوظائف الكلية والجهاز الهضمي وأمراض القلب.','الألم/الالتهاب، ضغط الدم، وظائف الكلية والآثار الخاصة بالدواء.','اختيار NSAID يعتمد على المريض والمخاطر أكثر من كونه “أقوى مسكن”.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["NSAID","COX-2"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('meloxicam','Meloxicam','ميلوكسيكام','M','Preferential COX-2 NSAID','PO',null,'Intermediate','ألم والتهاب مفصلي','يقلل prostaglandins عبر COX inhibition.','GI، renal، CV adverse effects.','مراعاة وظيفة الكلية/الكبد وخطر النزف أو التداخلات حسب الدواء.','تجنب الجمع العشوائي بين NSAIDs، وانتبه لوظائف الكلية والجهاز الهضمي وأمراض القلب.','الألم/الالتهاب، ضغط الدم، وظائف الكلية والآثار الخاصة بالدواء.','اختيار NSAID يعتمد على المريض والمخاطر أكثر من كونه “أقوى مسكن”.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["NSAID"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('colchicine','Colchicine','كولشيسين','M','Antigout anti-inflammatory','PO',null,'Intermediate','نوبات النقرس والوقاية من flare في سياقات مناسبة','يثبط microtubule polymerization ويقلل هجرة العدلات.','إسهال/قيء؛ سمية نخاع/عضلات وعصبية في الجرعات السامة.','القصور الكلوي والتداخلات CYP3A4/P-gp مهمة.','تجنب الجمع العشوائي بين NSAIDs، وانتبه لوظائف الكلية والجهاز الهضمي وأمراض القلب.','الألم/الالتهاب، ضغط الدم، وظائف الكلية والآثار الخاصة بالدواء.','اختيار NSAID يعتمد على المريض والمخاطر أكثر من كونه “أقوى مسكن”.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Gout"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('febuxostat','Febuxostat','فيبوكسوستات','M','Xanthine oxidase inhibitor','PO',null,'Intermediate','خفض حمض اليوريك في مرضى مختارين','يثبط xanthine oxidase بشكل انتقائي.','اضطرابات كبد، نوبات نقرس، اعتبارات قلبية حسب المريض.','مراعاة وظيفة الكلية/الكبد وخطر النزف أو التداخلات حسب الدواء.','تجنب الجمع العشوائي بين NSAIDs، وانتبه لوظائف الكلية والجهاز الهضمي وأمراض القلب.','الألم/الالتهاب، ضغط الدم، وظائف الكلية والآثار الخاصة بالدواء.','اختيار NSAID يعتمد على المريض والمخاطر أكثر من كونه “أقوى مسكن”.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Gout"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('methocarbamol','Methocarbamol','ميثوكاربامول','M','Skeletal muscle relaxant','PO / IV / IM',null,'Intermediate','تشنج عضلي مؤلم في حالات محددة','تأثير مركزي مثبط دون آلية طرفية واضحة.','نعاس، دوخة، تشوش.','مراعاة وظيفة الكلية/الكبد وخطر النزف أو التداخلات حسب الدواء.','تجنب الجمع العشوائي بين NSAIDs، وانتبه لوظائف الكلية والجهاز الهضمي وأمراض القلب.','الألم/الالتهاب، ضغط الدم، وظائف الكلية والآثار الخاصة بالدواء.','اختيار NSAID يعتمد على المريض والمخاطر أكثر من كونه “أقوى مسكن”.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Muscle spasm"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('tizanidine','Tizanidine','تيزانيدين','M','Alpha2 agonist muscle relaxant','PO',null,'Intermediate','تشنج عضلي في حالات عصبية','ينشط α2 مركزيًا ويقلل نشاط interneurons.','نعاس، انخفاض ضغط، جفاف، سمية كبدية.','مراعاة وظيفة الكلية/الكبد وخطر النزف أو التداخلات حسب الدواء.','تجنب الجمع العشوائي بين NSAIDs، وانتبه لوظائف الكلية والجهاز الهضمي وأمراض القلب.','الألم/الالتهاب، ضغط الدم، وظائف الكلية والآثار الخاصة بالدواء.','اختيار NSAID يعتمد على المريض والمخاطر أكثر من كونه “أقوى مسكن”.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Spasticity"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('baclofen','Baclofen','باكلوفين','M','GABA-B agonist','PO / Intrathecal',null,'Intermediate','spasticity','ينشط GABA-B ويقلل excitatory neurotransmission في الحبل الشوكي.','نعاس، ضعف؛ withdrawal خطير إذا أوقف فجأة، خصوصًا intrathecal.','مراعاة وظيفة الكلية/الكبد وخطر النزف أو التداخلات حسب الدواء.','تجنب الجمع العشوائي بين NSAIDs، وانتبه لوظائف الكلية والجهاز الهضمي وأمراض القلب.','الألم/الالتهاب، ضغط الدم، وظائف الكلية والآثار الخاصة بالدواء.','اختيار NSAID يعتمد على المريض والمخاطر أكثر من كونه “أقوى مسكن”.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Spasticity"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('vitamin-d3','Vitamin D3','فيتامين D3','M','Vitamin D supplement','PO',null,'Intermediate','نقص فيتامين D ودعم صحة العظام وفق الحاجة','يتحول إلى أشكال فعالة تنظم calcium/phosphate homeostasis.','فرط كالسيوم عند الإفراط.','مراعاة وظيفة الكلية/الكبد وخطر النزف أو التداخلات حسب الدواء.','تجنب الجمع العشوائي بين NSAIDs، وانتبه لوظائف الكلية والجهاز الهضمي وأمراض القلب.','الألم/الالتهاب، ضغط الدم، وظائف الكلية والآثار الخاصة بالدواء.','اختيار NSAID يعتمد على المريض والمخاطر أكثر من كونه “أقوى مسكن”.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Vitamin D"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('calcium-carbonate','Calcium carbonate','كربونات الكالسيوم','M','Calcium supplement / Antacid','PO',null,'Intermediate','نقص الكالسيوم وantacid في بعض المستحضرات','يوفر Ca ويعادل حمض المعدة.','إمساك، فرط كالسيوم؛ kidney stones عند الإفراط.','مراعاة وظيفة الكلية/الكبد وخطر النزف أو التداخلات حسب الدواء.','تجنب الجمع العشوائي بين NSAIDs، وانتبه لوظائف الكلية والجهاز الهضمي وأمراض القلب.','الألم/الالتهاب، ضغط الدم، وظائف الكلية والآثار الخاصة بالدواء.','اختيار NSAID يعتمد على المريض والمخاطر أكثر من كونه “أقوى مسكن”.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Calcium"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('zoledronic-acid','Zoledronic acid','زوليدرونيك أسيد','M','Bisphosphonate','IV',null,'Intermediate','هشاشة العظام وبعض أمراض العظم/الأورام','يثبط osteoclasts عبر مسار mevalonate.','أعراض شبيهة بالإنفلونزا، أذى كلوي، hypocalcemia، ONJ نادر.','مراعاة وظيفة الكلية/الكبد وخطر النزف أو التداخلات حسب الدواء.','تجنب الجمع العشوائي بين NSAIDs، وانتبه لوظائف الكلية والجهاز الهضمي وأمراض القلب.','الألم/الالتهاب، ضغط الدم، وظائف الكلية والآثار الخاصة بالدواء.','اختيار NSAID يعتمد على المريض والمخاطر أكثر من كونه “أقوى مسكن”.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Osteoporosis","Bone metastases"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('morphine','Morphine','مورفين','N','Opioid analgesic','PO / IV / IM / SC',null,'Intermediate','ألم شديد في سياقات مناسبة','ناهض μ-opioid يقلل نقل الألم ويغير الاستجابة له.','تثبيط تنفس، نعاس، إمساك، غثيان، اعتماد.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Opioid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('tramadol','Tramadol','ترامادول','N','Opioid analgesic / SNRI-like','PO / IV',null,'Intermediate','ألم متوسط إلى شديد في حالات محددة','ناهض μ ضعيف ويثبط reuptake لـ5-HT/NE.','نعاس، غثيان، seizures وserotonin syndrome مع تداخلات.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Opioid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('gabapentin','Gabapentin','غابابنتين','N','Neuropathic pain / antiseizure','PO',null,'Intermediate','ألم عصبي وبعض أنواع الصرع','يرتبط بوحدة α2δ لقنوات الكالسيوم ويقلل excitatory release.','دوخة، نعاس، وذمة؛ respiratory depression مع مثبطات أخرى في فئات معينة.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Neuropathic pain"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('pregabalin','Pregabalin','بريغابالين','N','Neuropathic pain / antiseizure','PO',null,'Intermediate','ألم عصبي وبعض حالات الصرع/القلق حسب المنتج','يرتبط α2δ ويقلل إطلاق الناقلات العصبية.','دوخة، نعاس، وذمة، زيادة وزن.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Neuropathic pain"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('amitriptyline','Amitriptyline','أميتريبتيلين','N','Tricyclic antidepressant','PO',null,'Intermediate','اكتئاب في بعض الحالات، ألم عصبي، الوقاية من الشقيقة حسب الممارسة','يثبط reuptake لـ5-HT وNE وله تأثيرات مضادة للمسكارين.','جفاف الفم، نعاس، QT/arrhythmia، سمية قاتلة في overdose.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["TCA","Neuropathic pain"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('fluoxetine','Fluoxetine','فلوكسيتين','N','SSRI','PO',null,'Intermediate','الاكتئاب وبعض اضطرابات القلق/الوسواس','يثبط serotonin reuptake.','غثيان، أرق، sexual dysfunction، serotonin syndrome.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["SSRI"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('escitalopram','Escitalopram','إسيتالوبرام','N','SSRI','PO',null,'Intermediate','الاكتئاب والقلق','يثبط serotonin reuptake.','غثيان، أرق/نعاس، sexual dysfunction، QT بجرعات/فئات معينة.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["SSRI"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('duloxetine','Duloxetine','دولوكستين','N','SNRI','PO',null,'Intermediate','الاكتئاب/القلق وألم عصبي وبعض الآلام المزمنة','يثبط reuptake لـ5-HT وNE.','غثيان، جفاف فم، ارتفاع ضغط، withdrawal عند الإيقاف المفاجئ.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["SNRI","Neuropathic pain"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('venlafaxine','Venlafaxine','فينلافاكسين','N','SNRI','PO',null,'Intermediate','الاكتئاب واضطرابات القلق','يثبط reuptake لـ5-HT وNE، وبجرعات أعلى تأثير noradrenergic أوضح.','غثيان، ارتفاع ضغط، withdrawal.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["SNRI"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('mirtazapine','Mirtazapine','ميرتازابين','N','Noradrenergic/serotonergic antidepressant','PO',null,'Intermediate','الاكتئاب مع أرق/نقص شهية عند بعض المرضى','يعمل كمضاد α2 المركزي و5-HT2/5-HT3.','نعاس، زيادة شهية/وزن.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Depression"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('risperidone','Risperidone','ريسبيريدون','N','Atypical antipsychotic','PO / LAI',null,'Intermediate','الفصام واضطرابات نفسية محددة','يؤثر في D2 و5-HT2A receptors.','أعراض خارج هرمية، ارتفاع prolactin، زيادة وزن/استقلاب.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antipsychotic"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('olanzapine','Olanzapine','أولانزابين','N','Atypical antipsychotic','PO / IM',null,'Intermediate','الفصام وثنائي القطب في الاستطبابات المناسبة','D2/5-HT2A antagonism مع تأثيرات مستقبلية متعددة.','زيادة وزن واستقلاب، نعاس، orthostasis.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antipsychotic"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('haloperidol','Haloperidol','هالوبيريدول','N','Typical antipsychotic','PO / IM / IV (protocol-specific)',null,'Intermediate','ذهان وهياج حاد وبعض الحالات حسب البروتوكول','حاصر D2 قوي.','EPS، tardive dyskinesia، QT، NMS.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antipsychotic","Acute agitation"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('lorazepam','Lorazepam','لورازيبام','N','Benzodiazepine','PO / IV / IM',null,'Intermediate','قلق شديد/تشنجات/انسحاب كحولي وبعض الاستعمالات الحادة','يعزز GABA-A عبر زيادة تكرار فتح القناة.','نعاس، تثبيط تنفس، اعتماد، ترنح.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Benzodiazepine"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('diazepam','Diazepam','ديازيبام','N','Benzodiazepine','PO / IV / Rectal',null,'Intermediate','تشنجات، قلق، تشنج عضلي واستعمالات حادة محددة','يعزز GABA-A.','نعاس، تثبيط تنفس، اعتماد وطول نصف عمر.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Benzodiazepine"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('carbamazepine','Carbamazepine','كاربامازيبين','N','Antiseizure','PO',null,'Intermediate','صرع وبعض حالات trigeminal neuralgia','يثبط voltage-gated sodium channels.','دوخة، hyponatremia، rash/SJS، agranulocytosis؛ enzyme inducer.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Epilepsy"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('lamotrigine','Lamotrigine','لاموتريجين','N','Antiseizure / mood stabilizer','PO',null,'Intermediate','صرع واضطراب ثنائي القطب للوقاية من النوبات المزاجية','يثبط sodium channels ويقلل glutamate release.','طفح خطير/SJS، دوخة، diplopia.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Epilepsy","Bipolar"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('valproate','Valproate','فالبروات','N','Antiseizure / mood stabilizer','PO / IV',null,'Intermediate','صرع وثنائي القطب/وقاية الشقيقة في استطبابات محددة','يزيد GABA ويؤثر في sodium channels.','سمية كبد، thrombocytopenia، زيادة وزن، pancreatitis، teratogenicity.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Epilepsy","Bipolar"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('topiramate','Topiramate','توبيراميت','N','Antiseizure / migraine prevention','PO',null,'Intermediate','صرع ووقاية الشقيقة','يثبط Na channels ويعزز GABA ويثبط AMPA ويؤثر في carbonic anhydrase.','تنميل، نقص وزن، cognitive slowing، stones، metabolic acidosis.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Epilepsy","Migraine"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('sumatriptan','Sumatriptan','سوماتريبتان','N','Triptan','PO / IN / SC',null,'Intermediate','علاج نوبة الشقيقة الحادة وليس الوقاية','ناهض 5-HT1B/1D يسبب تضيق أوعية قحفية ويثبط neuropeptide release.','إحساس ضغط/تنميل، نعاس؛ خطر وعائي لدى فئات مختارة.','موانع في أمراض وعائية معينة وبعض التداخلات serotoninergic.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Migraine"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('donepezil','Donepezil','دونيبيزيل','N','Acetylcholinesterase inhibitor','PO',null,'Intermediate','أعراض Alzheimer dementia الخفيفة-الشديدة حسب المنتج','يثبط acetylcholinesterase ويزيد acetylcholine مركزيًا.','غثيان، إسهال، بطء قلب، أحلام/أرق.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Dementia"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('levodopa-carbidopa','Levodopa/carbidopa','ليفودوبا/كاربيدوبا','N','Dopamine replacement','PO',null,'Intermediate','أعراض Parkinson disease','levodopa يتحول إلى dopamine في الدماغ وcarbidopa يثبط DOPA decarboxylase محيطيًا.','غثيان، dyskinesia، orthostasis، hallucinations.','راجع الحالة السريرية والتداخلات.','تجنّب التوقف المفاجئ لبعض هذه الأدوية، وانتبه للنعاس والتداخلات والقيادة.','الأعراض المستهدفة، الوعي، الآثار الجانبية، ووظائف الأعضاء الخاصة بالدواء.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Parkinson"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ivermectin','Ivermectin','إيفرمكتين','P','Antiparasitic','PO / Topical',null,'Intermediate','بعض الديدان والجرب/القمل وفق الاستطباب','يفتح قنوات كلوريد مرتبطة بالغلوتمات في الطفيليات مسببًا شللها.','دوخة، GI؛ تفاعلات نادرة مرتبطة بعبء الطفيليات.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','التقيد بطريقة التطبيق/الجرعة وإجراءات مكافحة العدوى أو المخالطين مهم في كثير من الطفيليات.','الاستجابة، الآثار الموضعية/الجهازية، وإعادة التقييم عند استمرار الأعراض.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Scabies","Helminths"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('mebendazole','Mebendazole','ميبيندازول','P','Benzimidazole anthelmintic','PO',null,'Intermediate','الديدان المعوية مثل pinworm/roundworm وفق الاستطباب','يعيق microtubules وامتصاص الغلوكوز في الطفيلي.','ألم بطني؛ إنزيمات كبد مع الاستخدام المطول.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','التقيد بطريقة التطبيق/الجرعة وإجراءات مكافحة العدوى أو المخالطين مهم في كثير من الطفيليات.','الاستجابة، الآثار الموضعية/الجهازية، وإعادة التقييم عند استمرار الأعراض.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Helminths"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('praziquantel','Praziquantel','برازيكوانتيل','P','Anthelmintic','PO',null,'Intermediate','schistosomiasis وبعض الديدان المفلطحة','يزيد نفاذية Ca في الديدان فيسبب شللها وموتها.','دوخة، صداع، ألم بطني بسبب موت الطفيليات.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','التقيد بطريقة التطبيق/الجرعة وإجراءات مكافحة العدوى أو المخالطين مهم في كثير من الطفيليات.','الاستجابة، الآثار الموضعية/الجهازية، وإعادة التقييم عند استمرار الأعراض.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Schistosomiasis"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('tinidazole','Tinidazole','تينيدازول','P','Nitroimidazole','PO',null,'Intermediate','بعض protozoal/anaerobic infections','يؤذي DNA بعد اختزال الدواء داخل الكائنات الحساسة.','GI، طعم معدني، neuropathy نادر.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','التقيد بطريقة التطبيق/الجرعة وإجراءات مكافحة العدوى أو المخالطين مهم في كثير من الطفيليات.','الاستجابة، الآثار الموضعية/الجهازية، وإعادة التقييم عند استمرار الأعراض.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Protozoa","Anaerobes"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('artemether-lumefantrine','Artemether/lumefantrine','أرتيميثير/لوميفانترين','P','Antimalarial ACT','PO',null,'Intermediate','ملاريا غير معقدة بسبب P. falciparum في مناطق/إرشادات مناسبة','artemisinin derivative يولد نواتج تفاعلية؛ lumefantrine يثبط detoxification of heme في الطفيلي.','GI، QT prolongation، دوخة.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','التقيد بطريقة التطبيق/الجرعة وإجراءات مكافحة العدوى أو المخالطين مهم في كثير من الطفيليات.','الاستجابة، الآثار الموضعية/الجهازية، وإعادة التقييم عند استمرار الأعراض.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Malaria"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('permethrin-1','Permethrin 1%','بيرمثرين 1%','P','Topical pediculicide','Topical',null,'Intermediate','قمل الرأس','يعطل قنوات الصوديوم في الطفيليات.','تهيج جلدي أو حكة مؤقتة.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','التقيد بطريقة التطبيق/الجرعة وإجراءات مكافحة العدوى أو المخالطين مهم في كثير من الطفيليات.','الاستجابة، الآثار الموضعية/الجهازية، وإعادة التقييم عند استمرار الأعراض.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Lice"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ipratropium','Ipratropium','إبراتروبيوم','R','Short-acting muscarinic antagonist','Inhaled',null,'Intermediate','COPD وبعض حالات التشنج القصبي','يحصر muscarinic receptors في الشعب ويقلل bronchoconstriction.','جفاف فم، طعم مر؛ glaucoma/urinary retention عند الامتصاص أو التعرض.','الحالة القلبية/الضغطية والتداخلات مهمة حسب الدواء.','تعلم تقنية جهاز الاستنشاق الصحيحة، ولا تعتمد على أدوية الإنقاذ إذا كانت السيطرة ضعيفة.','الأعراض، تكرار استخدام rescue therapy، التقنية والآثار الجانبية.','تقنية الاستنشاق والالتزام جزء من العلاج، وليسا تفصيلًا ثانويًا.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["COPD","Bronchodilator"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('tiotropium','Tiotropium','تيوتروبيوم','R','Long-acting muscarinic antagonist','Inhaled',null,'Intermediate','العلاج طويل الأمد لـCOPD وبعض أنظمة الربو','يحصر muscarinic receptors طويل المفعول ويقلل bronchoconstriction.','جفاف فم؛ urinary retention/glaucoma risk.','الحالة القلبية/الضغطية والتداخلات مهمة حسب الدواء.','تعلم تقنية جهاز الاستنشاق الصحيحة، ولا تعتمد على أدوية الإنقاذ إذا كانت السيطرة ضعيفة.','الأعراض، تكرار استخدام rescue therapy، التقنية والآثار الجانبية.','تقنية الاستنشاق والالتزام جزء من العلاج، وليسا تفصيلًا ثانويًا.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["COPD","LAMA"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('formoterol','Formoterol','فورموتيرول','R','Long-acting beta2 agonist','Inhaled',null,'Intermediate','السيطرة على الربو/COPD ضمن التركيبات المناسبة','ينشط β2 طويل المفعول ويسبب bronchodilation.','رجفة، خفقان، نقص K.','الحالة القلبية/الضغطية والتداخلات مهمة حسب الدواء.','تعلم تقنية جهاز الاستنشاق الصحيحة، ولا تعتمد على أدوية الإنقاذ إذا كانت السيطرة ضعيفة.','الأعراض، تكرار استخدام rescue therapy، التقنية والآثار الجانبية.','تقنية الاستنشاق والالتزام جزء من العلاج، وليسا تفصيلًا ثانويًا.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["LABA"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('salmeterol','Salmeterol','سالميتيرول','R','Long-acting beta2 agonist','Inhaled',null,'Intermediate','السيطرة طويلة الأمد على الربو/COPD مع العلاج المضاد للالتهاب عند الحاجة','ينشط β2 طويل المفعول.','رجفة وخفقان ونقص K.','الحالة القلبية/الضغطية والتداخلات مهمة حسب الدواء.','تعلم تقنية جهاز الاستنشاق الصحيحة، ولا تعتمد على أدوية الإنقاذ إذا كانت السيطرة ضعيفة.','الأعراض، تكرار استخدام rescue therapy، التقنية والآثار الجانبية.','تقنية الاستنشاق والالتزام جزء من العلاج، وليسا تفصيلًا ثانويًا.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["LABA"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('fluticasone-inhaled','Fluticasone inhaled','فلوتيكازون مستنشق','R','Inhaled corticosteroid','Inhaled',null,'Intermediate','السيطرة على الربو وبعض الأنظمة التنفسية','يقلل الالتهاب الهوائي عبر glucocorticoid receptor.','بحة، oral candidiasis، آثار جهازية عند الجرعات العالية.','الحالة القلبية/الضغطية والتداخلات مهمة حسب الدواء.','تعلم تقنية جهاز الاستنشاق الصحيحة، ولا تعتمد على أدوية الإنقاذ إذا كانت السيطرة ضعيفة.','الأعراض، تكرار استخدام rescue therapy، التقنية والآثار الجانبية.','تقنية الاستنشاق والالتزام جزء من العلاج، وليسا تفصيلًا ثانويًا.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Asthma","ICS"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('montelukast','Montelukast','مونتيلوكاست','R','Leukotriene receptor antagonist','PO',null,'Intermediate','الربو وبعض حالات allergic rhinitis','يحصر CysLT1 ويقلل تأثير leukotrienes.','صداع؛ أحداث neuropsychiatric قد تحدث.','الحالة القلبية/الضغطية والتداخلات مهمة حسب الدواء.','تعلم تقنية جهاز الاستنشاق الصحيحة، ولا تعتمد على أدوية الإنقاذ إذا كانت السيطرة ضعيفة.','الأعراض، تكرار استخدام rescue therapy، التقنية والآثار الجانبية.','تقنية الاستنشاق والالتزام جزء من العلاج، وليسا تفصيلًا ثانويًا.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Asthma","Allergy"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('theophylline','Theophylline','ثيوفيلين','R','Methylxanthine bronchodilator','PO',null,'Intermediate','استعمالات تنفسية مختارة بسبب هامش علاجي ضيق','يثبط phosphodiesterase ويؤثر على adenosine receptors.','غثيان، رجفة، خفقان، seizures/arrhythmias عند السمية.','الحالة القلبية/الضغطية والتداخلات مهمة حسب الدواء.','تعلم تقنية جهاز الاستنشاق الصحيحة، ولا تعتمد على أدوية الإنقاذ إذا كانت السيطرة ضعيفة.','الأعراض، تكرار استخدام rescue therapy، التقنية والآثار الجانبية.','تقنية الاستنشاق والالتزام جزء من العلاج، وليسا تفصيلًا ثانويًا.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Asthma","COPD"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('guaifenesin','Guaifenesin','غوايفينيسين','R','Expectorant','PO',null,'Intermediate','تخفيف السعال المنتج للإفرازات في بعض الحالات','يزيد hydration of respiratory secretions ويسهّل إخراجها.','غثيان، دوخة.','الحالة القلبية/الضغطية والتداخلات مهمة حسب الدواء.','تعلم تقنية جهاز الاستنشاق الصحيحة، ولا تعتمد على أدوية الإنقاذ إذا كانت السيطرة ضعيفة.','الأعراض، تكرار استخدام rescue therapy، التقنية والآثار الجانبية.','تقنية الاستنشاق والالتزام جزء من العلاج، وليسا تفصيلًا ثانويًا.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cough"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('dextromethorphan','Dextromethorphan','ديكستروميثورفان','R','Antitussive','PO',null,'Intermediate','السعال الجاف في بعض المستحضرات','تأثير مركزي مضاد للسعال؛ له تأثيرات على NMDA/σ receptor.','نعاس، دوخة؛ serotonin syndrome مع بعض الأدوية بجرعات/تداخلات.','الحالة القلبية/الضغطية والتداخلات مهمة حسب الدواء.','تعلم تقنية جهاز الاستنشاق الصحيحة، ولا تعتمد على أدوية الإنقاذ إذا كانت السيطرة ضعيفة.','الأعراض، تكرار استخدام rescue therapy، التقنية والآثار الجانبية.','تقنية الاستنشاق والالتزام جزء من العلاج، وليسا تفصيلًا ثانويًا.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cough"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('pseudoephedrine','Pseudoephedrine','سودوإيفيدرين','R','Sympathomimetic decongestant','PO',null,'Intermediate','احتقان الأنف على المدى القصير في حالات مختارة','ينشط α/β بشكل غير مباشر ويقلل احتقان الغشاء المخاطي.','ارتفاع ضغط، خفقان، أرق.','الحذر في HTN وبعض أمراض القلب؛ قوانين الصرف تختلف.','تعلم تقنية جهاز الاستنشاق الصحيحة، ولا تعتمد على أدوية الإنقاذ إذا كانت السيطرة ضعيفة.','الأعراض، تكرار استخدام rescue therapy، التقنية والآثار الجانبية.','تقنية الاستنشاق والالتزام جزء من العلاج، وليسا تفصيلًا ثانويًا.','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Decongestant"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('latanoprost','Latanoprost','لاتانوبروست','S','Prostaglandin F2α analog','Ophthalmic',null,'Intermediate','خفض ضغط العين في glaucoma/ocular hypertension','يزيد uveoscleral outflow.','احمرار، نمو الرموش، تصبغ القزحية/الجلد حول العين.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','لا تلمس طرف القطارة العين، وراقب الألم/تدهور الرؤية أو التحسس.','IOP أو الالتهاب أو الأعراض حسب الاستطباب.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Glaucoma"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('brimonidine','Brimonidine','بريمونيدين','S','Alpha2 agonist ophthalmic','Ophthalmic',null,'Intermediate','خفض IOP في glaucoma','يقلل aqueous humor ويزيد uveoscleral outflow.','احمرار، جفاف، نعاس/هبوط ضغط نادرًا.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','لا تلمس طرف القطارة العين، وراقب الألم/تدهور الرؤية أو التحسس.','IOP أو الالتهاب أو الأعراض حسب الاستطباب.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Glaucoma"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('dorzolamide','Dorzolamide','دورزولاميد','S','Carbonic anhydrase inhibitor ophthalmic','Ophthalmic',null,'Intermediate','خفض IOP في glaucoma','يثبط carbonic anhydrase في ciliary body ويقلل aqueous humor.','حرقان، طعم مر.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','لا تلمس طرف القطارة العين، وراقب الألم/تدهور الرؤية أو التحسس.','IOP أو الالتهاب أو الأعراض حسب الاستطباب.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Glaucoma"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('olopatadine','Olopatadine','أولوباتادين','S','Antihistamine/mast-cell stabilizer','Ophthalmic',null,'Intermediate','حكة العين التحسسية','يحصر H1 ويثبت mast cells.','تهيج وجفاف مؤقت.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','لا تلمس طرف القطارة العين، وراقب الألم/تدهور الرؤية أو التحسس.','IOP أو الالتهاب أو الأعراض حسب الاستطباب.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Allergic conjunctivitis"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('moxifloxacin-ophthalmic','Moxifloxacin ophthalmic','موكسيفلوكساسين عيني','S','Fluoroquinolone antibiotic','Ophthalmic',null,'Intermediate','عدوى بكتيرية سطحية للعين حسب التشخيص','يثبط bacterial DNA gyrase/topoisomerase IV.','تهيج، جفاف.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','لا تلمس طرف القطارة العين، وراقب الألم/تدهور الرؤية أو التحسس.','IOP أو الالتهاب أو الأعراض حسب الاستطباب.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Eye infection"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('ciprofloxacin-otic','Ciprofloxacin otic','سيبروفلوكساسين أذني','S','Fluoroquinolone antibiotic','Otic',null,'Intermediate','التهابات الأذن البكتيرية المحددة','يثبط DNA gyrase/topoisomerase IV.','حكة/تهيج موضعي.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','لا تلمس طرف القطارة العين، وراقب الألم/تدهور الرؤية أو التحسس.','IOP أو الالتهاب أو الأعراض حسب الاستطباب.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Otitis"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('dexamethasone-ophthalmic','Dexamethasone ophthalmic','ديكساميثازون عيني','S','Ophthalmic corticosteroid','Ophthalmic',null,'Intermediate','التهاب العين في حالات مختارة بعد استبعاد العدوى المناسبة','يقلل الالتهاب عبر glucocorticoid receptor.','ارتفاع IOP، cataract، تأخر التئام؛ قد يفاقم العدوى.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','لا تلمس طرف القطارة العين، وراقب الألم/تدهور الرؤية أو التحسس.','IOP أو الالتهاب أو الأعراض حسب الاستطباب.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Ophthalmic steroid"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('atropine-ophthalmic','Atropine ophthalmic','أتروبين عيني','S','Antimuscarinic','Ophthalmic',null,'Intermediate','Mydriasis/cycloplegia في الفحص وبعض العلاجات','يحصر muscarinic receptors في العضلة القزحية والهدبية.','حساسية للضوء، غشاوة رؤية، تأثيرات جهازية نادرة.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','لا تلمس طرف القطارة العين، وراقب الألم/تدهور الرؤية أو التحسس.','IOP أو الالتهاب أو الأعراض حسب الاستطباب.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Cycloplegia"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('flumazenil','Flumazenil','فلومازينيل','V','Benzodiazepine antagonist','IV',null,'Intermediate','عكس تأثير benzodiazepines في حالات مختارة','ينافس benzodiazepines على GABA-A receptor site.','Seizures وwithdrawal في المعتمدين؛ عودة التهدئة.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','أدوية إسعافية/عالية الخطورة وتُستخدم ضمن بروتوكولات طبية مع دعم ABC.','العلامات الحيوية، الاستجابة للسمية، ومراقبة الأعضاء حسب الترياق.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antidote"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('protamine','Protamine','بروتامين','V','Heparin antagonist','IV',null,'Intermediate','عكس heparin في حالات محددة','يرتبط بالهيبارين ويعادل تأثيره.','هبوط ضغط/تحسس ومضاعفات رئوية نادرة.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','أدوية إسعافية/عالية الخطورة وتُستخدم ضمن بروتوكولات طبية مع دعم ABC.','العلامات الحيوية، الاستجابة للسمية، ومراقبة الأعضاء حسب الترياق.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antidote"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('n-acetylcysteine','N-acetylcysteine','إن-أسيتيل سيستئين','V','Antidote / mucolytic','PO / IV / Inhaled',null,'Intermediate','علاج تسمم paracetamol وفي بعض الاستطبابات التنفسية','يعيد glutathione ويساهم في إزالة NAPQI؛ ويقلل لزوجة الإفرازات.','غثيان؛ تفاعلات infusion/anaphylactoid مع IV.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','أدوية إسعافية/عالية الخطورة وتُستخدم ضمن بروتوكولات طبية مع دعم ABC.','العلامات الحيوية، الاستجابة للسمية، ومراقبة الأعضاء حسب الترياق.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antidote","Acetaminophen overdose"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('atropine','Atropine','أتروبين','V','Antimuscarinic','IV / IM / SC',null,'Intermediate','بطء قلب عرضي وبعض حالات التسمم الكوليني','يحصر muscarinic receptors.','جفاف، تسرع قلب، تشوش، احتباس بول.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','أدوية إسعافية/عالية الخطورة وتُستخدم ضمن بروتوكولات طبية مع دعم ABC.','العلامات الحيوية، الاستجابة للسمية، ومراقبة الأعضاء حسب الترياق.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antidote","Bradycardia"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('pralidoxime','Pralidoxime','براليدوكسيم','V','Cholinesterase reactivator','IV / IM',null,'Intermediate','تسمم organophosphate مع atropine في البروتوكولات','يعيد تنشيط acetylcholinesterase قبل aging لبعض المركبات.','تسرع قلب، ارتفاع ضغط، ضعف عضلي/دوار.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','أدوية إسعافية/عالية الخطورة وتُستخدم ضمن بروتوكولات طبية مع دعم ABC.','العلامات الحيوية، الاستجابة للسمية، ومراقبة الأعضاء حسب الترياق.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Organophosphate"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.drugs(id,name,ar,system,class,route,atc,level,uses,moa,adr,contra,counsel,monitor,pearls,dose,tags) values ('hydroxocobalamin','Hydroxocobalamin','هيدروكسوكوبالامين','V','Cyanide antidote','IV',null,'Intermediate','تسمم السيانيد في الحالات الإسعافية','يرتبط بالسيانيد ويكوّن cyanocobalamin غير سام نسبيًا.','ارتفاع ضغط، احمرار/تلون الجلد والبول، تداخل مع بعض المختبرات.','راجع المنتج والحالة السريرية؛ الموانع تختلف حسب الاستطباب.','أدوية إسعافية/عالية الخطورة وتُستخدم ضمن بروتوكولات طبية مع دعم ABC.','العلامات الحيوية، الاستجابة للسمية، ومراقبة الأعضاء حسب الترياق.','','الجرعة تعتمد على الاستطباب والعمر ووظائف الكلية/الكبد والمنتج. راجع مرجعًا حديثًا.','["Antidote","Cyanide"]'::jsonb) on conflict (id) do update set name=excluded.name,ar=excluded.ar,system=excluded.system,class=excluded.class,route=excluded.route,atc=excluded.atc,level=excluded.level,uses=excluded.uses,moa=excluded.moa,adr=excluded.adr,contra=excluded.contra,counsel=excluded.counsel,monitor=excluded.monitor,pearls=excluded.pearls,dose=excluded.dose,tags=excluded.tags,updated_at=now();
insert into public.interactions(id,a,b,severity,title,summary) values ('warfarin-nsaid','warfarin','ibuprofen','high','Warfarin + NSAID','يزداد خطر النزف عند الجمع؛ يجب تقييم الحاجة والمتابعة واختيار بديل عند الإمكان.') on conflict (id) do update set a=excluded.a,b=excluded.b,severity=excluded.severity,title=excluded.title,summary=excluded.summary,updated_at=now();
insert into public.interactions(id,a,b,severity,title,summary) values ('nitrate-sildenafil','nitroglycerin','sildenafil','contra','Nitrate + PDE5 inhibitor','الجمع قد يسبب هبوط ضغط خطير؛ يعد من التداخلات الممنوعة المعروفة.') on conflict (id) do update set a=excluded.a,b=excluded.b,severity=excluded.severity,title=excluded.title,summary=excluded.summary,updated_at=now();
insert into public.interactions(id,a,b,severity,title,summary) values ('sertraline-tramadol','sertraline','tramadol','high','SSRI + Tramadol','قد يزيد خطر serotonin syndrome وبعض التأثيرات العصبية؛ يلزم تقييم البدائل والمراقبة.') on conflict (id) do update set a=excluded.a,b=excluded.b,severity=excluded.severity,title=excluded.title,summary=excluded.summary,updated_at=now();
insert into public.interactions(id,a,b,severity,title,summary) values ('ace-k','lisinopril','spironolactone','high','ACE inhibitor + Spironolactone','قد يرتفع البوتاسيوم وتتغير وظيفة الكلية؛ يحتاج اختيارًا ومتابعة دقيقة.') on conflict (id) do update set a=excluded.a,b=excluded.b,severity=excluded.severity,title=excluded.title,summary=excluded.summary,updated_at=now();
insert into public.interactions(id,a,b,severity,title,summary) values ('statin-gemfibrozil','atorvastatin','gemfibrozil','high','Statin + Gemfibrozil','يزداد خطر myopathy/rhabdomyolysis؛ يفضل تجنب الجمع غير الضروري.') on conflict (id) do update set a=excluded.a,b=excluded.b,severity=excluded.severity,title=excluded.title,summary=excluded.summary,updated_at=now();
insert into public.interactions(id,a,b,severity,title,summary) values ('warfarin-amiodarone','warfarin','amiodarone','high','Warfarin + Amiodarone','قد يرتفع تأثير warfarin وINR بسبب التداخل؛ يحتاج متابعة INR وتعديل الخطة.') on conflict (id) do update set a=excluded.a,b=excluded.b,severity=excluded.severity,title=excluded.title,summary=excluded.summary,updated_at=now();
insert into public.cases(id,title,system,difficulty,stem,options,answer,why,tags) values ('case-warfarin','Warfarin + ارتفاع INR','B','متقدم','مريض على warfarin لديه ارتفاع في INR بعد بدء دواء جديد. ما أول فكرة دوائية يجب البحث عنها؟','["تداخل دوائي يزيد تأثير warfarin","زيادة امتصاص الحديد","تحفيز CYP3A4 فقط","نقص فيتامين C"]'::jsonb,0,'Warfarin شديد الحساسية للتداخلات الدوائية والغذائية ويحتاج تقييم INR واتجاهه.','["INR","Interactions"]'::jsonb) on conflict (id) do update set title=excluded.title,system=excluded.system,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,why=excluded.why,tags=excluded.tags;
insert into public.cases(id,title,system,difficulty,stem,options,answer,why,tags) values ('case-ast-1','الربو والاستخدام المتكرر للـSABA','R','متوسط','طالب يستخدم salbutamol عدة مرات يوميًا. ما المفهوم الأهم؟','["هذا يعني أن العلاج مضبوط تمامًا","قد يدل على ضعف السيطرة ويحتاج مراجعة العلاج الوقائي","يجب مضاعفة SABA بلا حد","الـSABA يعالج الالتهاب المزمن"]'::jsonb,1,'الاعتماد المتكرر على دواء الإنقاذ يستدعي تقييم السيطرة وتقنية الاستنشاق والخطة المضادة للالتهاب.','["Asthma","SABA"]'::jsonb) on conflict (id) do update set title=excluded.title,system=excluded.system,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,why=excluded.why,tags=excluded.tags;
insert into public.cases(id,title,system,difficulty,stem,options,answer,why,tags) values ('case-metformin','Metformin ووظيفة الكلية','A','متوسط','عند متابعة مريض يستخدم metformin، أي معلومة دوائية أساسية لا ينبغي تجاهلها؟','["لون العين","eGFR","طول الشعر","نبض القدم"]'::jsonb,1,'وظيفة الكلية عنصر أساسي في تقييم أمان واستمرار metformin.','["Diabetes","Renal"]'::jsonb) on conflict (id) do update set title=excluded.title,system=excluded.system,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,why=excluded.why,tags=excluded.tags;
insert into public.cases(id,title,system,difficulty,stem,options,answer,why,tags) values ('case-pde5','ألم صدر + sildenafil','G','متقدم','مريض يستخدم sildenafil وأُعطي nitroglycerin لألم صدر. ما أهم مشكلة يجب التعرف عليها؟','["خطر هبوط ضغط شديد","زيادة LDL فقط","الإمساك فقط","انخفاض TSH"]'::jsonb,0,'PDE5 inhibitors مع nitrates قد تسبب vasodilation شديدة وهبوط ضغط خطير.','["Interaction","PDE5","Nitrates"]'::jsonb) on conflict (id) do update set title=excluded.title,system=excluded.system,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,why=excluded.why,tags=excluded.tags;
insert into public.cases(id,title,system,difficulty,stem,options,answer,why,tags) values ('case-ace-k','Lisinopril + spironolactone','C','متوسط','مريض على lisinopril بدأ spironolactone. أي متابعة دوائية تصبح مهمة؟','["Potassium وcreatinine","Hair color","Vitamin C فقط","Visual acuity فقط"]'::jsonb,0,'الجمع قد يرفع K ويؤثر في وظيفة الكلية.','["K","ACEI","MRA"]'::jsonb) on conflict (id) do update set title=excluded.title,system=excluded.system,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,why=excluded.why,tags=excluded.tags;
insert into public.cases(id,title,system,difficulty,stem,options,answer,why,tags) values ('case-nsaid','NSAID والمخاطر','M','متوسط','مريض لديه CKD ونزف هضمي سابق ويطلب ibuprofen. ما التفكير الصحيح؟','["مخاطر NSAID مرتفعة ويجب تقييم البديل","ibuprofen آمن دائمًا","الجرعة لا تهم","لا علاقة للكلية"]'::jsonb,0,'NSAIDs قد تزيد الأذى الكلوي والنزف، وتزداد الخطورة مع CKD والتاريخ الهضمي.','["NSAID","CKD"]'::jsonb) on conflict (id) do update set title=excluded.title,system=excluded.system,difficulty=excluded.difficulty,stem=excluded.stem,options=excluded.options,answer=excluded.answer,why=excluded.why,tags=excluded.tags;
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('gerd','GERD / الارتجاع','A','فكر أولًا في نمط الأعراض، علامات الإنذار، ثم تعديل نمط الحياة والعلاج الخافض للحمض عند وجود استطباب.','PPI عند المرضى المناسبين؛ اختَر الدواء والمدة حسب التشخيص والاستجابة.','H2 blocker في سياقات مختارة أو كإضافة ليلية لبعض المرضى.','لا تعالج أعراض إنذار أو dysphagia/نزف بشكل روتيني في المنزل دون تقييم.','الاستجابة، علامات الإنذار والحاجة لاستمرار العلاج.','راجع إرشادات الجهاز الهضمي المحلية والنشرة الحالية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('hypertension','Hypertension / ارتفاع الضغط','C','ابدأ بتأكيد التشخيص وتقدير الخطر القلبي الوعائي والأعضاء المستهدفة ثم اختر علاجًا مناسبًا للمريض.','ACEI/ARB، CCB أو thiazide-like diuretic خيارات أولية شائعة بحسب المريض والإرشادات.','Beta blocker أو أدوية أخرى في استطبابات خاصة.','لا تختَر العلاج اعتمادًا على رقم ضغط واحد فقط ولا تهمل الالتزام ونمط الحياة.','BP، electrolytes، renal function عند الأدوية التي تؤثر فيها.','راجع الإرشادات الوطنية/القلب الحديثة قبل أي قرار علاجي.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('type2dm','Type 2 Diabetes / السكري النوع 2','A','الاختيار يعتمد على HbA1c، الأعراض، الخطر القلبي/الكلوي، الوزن، القدرة على التحمل والتكلفة.','Metformin خيار شائع عند الملاءمة؛ GLP-1 RA أو SGLT2 inhibitor قد تكون ذات أولوية عند مخاطر قلبية/كلوية محددة.','DPP-4 inhibitor، sulfonylurea، TZD، insulin حسب الحالة.','لا تضع هدفًا واحدًا لكل المرضى ولا تتجاهل hypoglycemia risk.','HbA1c، glucose، weight وrenal function بحسب العلاج.','راجع إرشادات السكري الحديثة وخطة المريض الفردية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('asthma','Asthma / الربو','R','الأساس هو تقييم السيطرة، تقنية الاستنشاق، الالتزام وتجنب المحفزات؛ العلاج المضاد للالتهاب مهم عندما يكون مستطبًا.','ICS-containing therapy وفق شدة/نمط الربو والإرشادات؛ لا تعتمد على rescue bronchodilator وحده كخطة مزمنة.','ICS/LABA أو خيارات إضافية حسب الشدة.','الإفراط في SABA دون مراجعة السيطرة.','الأعراض، استخدام rescue، التقنية ووظيفة الرئة عند الحاجة.','راجع GINA والإرشادات المحلية الحالية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('copd','COPD / الانسداد الرئوي المزمن','R','الاختيار يعتمد على الأعراض، التفاقمات والتشخيص المؤكد مع الاهتمام بالإقلاع عن التدخين واللقاحات.','Bronchodilator طويل المفعول مثل LAMA أو LABA حسب النمط، مع تعديلات لاحقة حسب الاستجابة.','LABA/LAMA أو ICS-containing regimen في فئات مختارة.','ICS ليس علاجًا لكل مريض COPD بلا مؤشرات مناسبة.','الأعراض، التفاقمات، التقنية والآثار الجانبية.','راجع GOLD والتوصيات المحلية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('dyslipidemia','Dyslipidemia / اضطراب الدهون','C','قرار العلاج يعتمد على خطر ASCVD والـLDL وليس على الرقم وحده.','Statin بحدة مناسبة حسب مستوى الخطر.','Ezetimibe أو أدوية إضافية عند عدم الوصول للهدف أو عدم التحمل.','لا تستخدم مكملات أو تركيبات غير موثقة كبديل للعلاج المثبت.','Lipid panel، الأعراض العضلية وLFTs عند الحاجة.','راجع إرشادات الدهون/القلب الحالية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('uti','Uncomplicated UTI / التهاب المسالك غير المعقد','J','تأكد من التشخيص والسياق (العمر، الحمل، الجنس، الكلية، علامات pyelonephritis) قبل اختيار المضاد.','اختيار مضاد موصى به محليًا حسب المقاومة والمريض، وليس أي broad-spectrum عشوائي.','تختلف حسب البلد والحساسية والمزرعة.','لا تعالج asymptomatic bacteriuria لكل شخص.','الاستجابة، الحمى/ألم الخاصرة وعلامات العدوى المعقدة.','راجع إرشادات العدوى والمسالك المحلية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('cap','Community-acquired pneumonia / ذات الرئة المكتسبة من المجتمع','J','حدّد شدة المرض والحاجة للاستشفاء ثم اختر علاجًا مبنيًا على عوامل الخطورة والمقاومة.','نظام مضاد حيوي موجه حسب الشدة والسياق؛ لا يوجد نظام واحد لكل مريض.','بدائل حسب allergy، comorbidity، recent antibiotics والمقاومة.','لا تعالج كل سعال على أنه bacterial pneumonia.','الاستقرار السريري، الحرارة، الأكسجة والاستجابة.','راجع إرشادات الأمراض التنفسية/العدوى المحلية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('hpylori','H. pylori','A','يحتاج اختيار نظام متعدد الأدوية يعتمد على المقاومة المحلية والتعرض السابق للمضادات.','العلاج eradication combination من PPI مع مضادات مناسبة وفق الإرشادات.','Bismuth-based أو أنظمة أخرى بحسب المنطقة والمقاومة.','لا تعتمد وصفة ثابتة واحدة لكل البلدان أو بعد فشل سابق.','التزام المريض واختبار eradication بعد المدة المناسبة حسب الإرشادات.','راجع إرشادات H. pylori الحديثة.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('hfref','HFrEF / قصور القلب مع انخفاض EF','C','العلاج يعتمد على أدوية أساسية متعددة تُستخدم تدريجيًا بحسب التحمل، مع علاج الاحتقان عند الحاجة.','ARNI/ACEI/ARB، beta blocker مناسب، MRA وSGLT2 inhibitor هي محاور رئيسية عند الملاءمة.','Hydralazine/isosorbide وغيرها في سياقات خاصة.','بدء أو رفع كل دواء بسرعة دون مراقبة الضغط والكلية والبوتاسيوم.','BP، renal function، K، الوزن وأعراض الاحتقان.','راجع إرشادات قصور القلب الحديثة.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('af','Atrial fibrillation / الرجفان الأذيني','C','فكر في stroke prevention، ثم rate/rhythm control حسب نوع المريض والأعراض.','DOAC مناسب أو warfarin في حالات مختارة للوقاية الخثرية حسب الخطر؛ rate control غالبًا beta blocker أو CCB مناسب.','Digoxin أو rhythm-control strategies في فئات محددة.','لا تستخدم anticoagulation بلا تقييم خطر النزف/السكتة والموانع.','HR، ECG، renal function ومؤشرات النزف/الالتزام.','راجع إرشادات AF الحديثة.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('gout','Gout / النقرس','M','فرّق بين علاج النوبة وعلاج خفض حمض اليوريك طويل الأمد.','في flare: NSAID أو colchicine أو corticosteroid بحسب المريض؛ للوقاية المزمنة allopurinol خيار شائع.','Febuxostat أو خيارات أخرى عند عدم الملاءمة.','لا تبدأ/تعدل urate-lowering therapy بلا خطة للوقاية من flares والمتابعة.','Uric acid، renal function والآثار الجانبية.','راجع إرشادات النقرس الحديثة.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('migraine','Migraine / الشقيقة','N','حدد المحفزات، التشخيص، شدة النوبات وتكرارها؛ فرّق بين acute وpreventive therapy.','Triptan أو مسكن مناسب للنوبة عند الملاءمة؛ الوقاية تُفكر فيها عند كثرة/شدة النوبات.','Topiramate، بعض beta blockers أو خيارات أخرى حسب المريض.','الإفراط في المسكنات لتجنب medication-overuse headache.','أيام الصداع، الأعراض الجانبية واستخدام rescue medication.','راجع إرشادات الصداع الحالية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('depression','Major depressive disorder / الاكتئاب','N','التشخيص والمتابعة مهمان؛ العلاج يشمل psychotherapy، medication أو الاثنين حسب الحالة.','SSRI مثل sertraline أو escitalopram في كثير من المرضى المناسبين.','SNRI أو أدوية أخرى حسب الأعراض والأمراض المصاحبة.','لا توقف antidepressant فجأة دون خطة ولا تحكم على الفعالية بعد أيام قليلة فقط.','المزاج، الأعراض، الانتحارية حسب الخطر والآثار الجانبية والتداخلات.','راجع إرشادات الصحة النفسية الحالية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('eczema','Atopic dermatitis / الأكزيما','D','الأساس هو skin barrier care وتحديد شدة المرض ومسببات التفاقم.','Emollients مع topical anti-inflammatory مناسب للقوة والموقع.','Topical calcineurin inhibitor أو علاجات أخرى حسب الشدة.','الستيرويد القوي على الوجه أو الاستخدام الطويل العشوائي.','التحسن، العدوى والتأثيرات الموضعية.','راجع إرشادات الجلدية الحالية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('acne','Acne / حب الشباب','D','اختيار العلاج يعتمد على شدة acne ونوع الآفات والندبات.','Topical retinoid و/أو benzoyl peroxide، مع antibiotic topical في سياقات محددة وليس وحده لفترات طويلة.','علاج جهازي أو hormonal therapy حسب الشدة والملاءمة.','المضادات الحيوية الموضعية منفردة لفترات طويلة.','التهيج، الاستجابة والالتزام.','راجع إرشادات حب الشباب الحالية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('constipation','Constipation / الإمساك','A','استبعد الانسداد وعلامات الخطر ثم عالج السبب ونمط الحياة قبل تصعيد الدواء.','سوائل/ألياف ونشاط عند الملاءمة ثم osmotic laxative مثل PEG في كثير من المرضى.','Lactulose أو stimulant laxative عند الحاجة.','الاستخدام المزمن العشوائي للمنبهات دون تقييم السبب.','التبرز، الألم، الترطيب والشوارد عند الاستخدام الطويل.','راجع الإرشادات الهضمية الحالية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('hypothyroid','Hypothyroidism / قصور الدرق','H','Levothyroxine هو أساس التعويض عند تشخيص قصور الدرق الأولي؛ الجرعة تُفصل للمريض.','Levothyroxine مع ضبط تدريجي ومراعاة العمر/القلب والحمل.','استثناءات محدودة حسب الاختصاص؛ لا تستخدم T3 روتينيًا لكل المرضى.','تعديل الجرعة بناءً على أعراض منفردة دون TSH/السياق.','TSH وFree T4 حسب الحالة والزمن بعد التعديل.','راجع إرشادات الغدة الدرقية الحالية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.guides(id,title,system,summary,first_line,alternatives,avoid_text,monitor,source_note) values ('iron-deficiency','Iron-deficiency anemia / فقر الدم بعوز الحديد','B','عالج النقص وابحث عن السبب، خصوصًا النزف أو سوء الامتصاص.','Oral iron عندما يكون مناسبًا، مع تعديل الجدول لتحسين التحمل/الالتزام.','IV iron عند عدم التحمل أو سوء الامتصاص أو الحاجة السريعة في سياقات محددة.','معالجة CBC فقط دون تقييم سبب فقد الحديد.','Hb، ferritin/iron studies والاستجابة والتحمل.','راجع إرشادات فقر الدم والحديد الحالية.') on conflict (id) do update set title=excluded.title,system=excluded.system,summary=excluded.summary,first_line=excluded.first_line,alternatives=excluded.alternatives,avoid_text=excluded.avoid_text,monitor=excluded.monitor,source_note=excluded.source_note,updated_at=now();
insert into public.quiz_questions(id,question,answers,correct_index,explanation) values ('00000000-0000-0000-0000-000000000001','أي فئة دوائية تثبط H+/K+-ATPase في الخلايا الجدارية؟','["PPI","H2 blocker","Antacid فقط","Prokinetic"]'::jsonb,0,'PPIs هي مثبطات مضخة البروتون وتثبط H+/K+-ATPase.') on conflict (id) do update set question=excluded.question,answers=excluded.answers,correct_index=excluded.correct_index,explanation=excluded.explanation;
insert into public.quiz_questions(id,question,answers,correct_index,explanation) values ('00000000-0000-0000-0000-000000000002','ما الاختبار الأهم لمتابعة warfarin عادةً؟','["INR","HbA1c","TSH","Troponin"]'::jsonb,0,'INR جزء أساسي من متابعة warfarin.') on conflict (id) do update set question=excluded.question,answers=excluded.answers,correct_index=excluded.correct_index,explanation=excluded.explanation;
insert into public.quiz_questions(id,question,answers,correct_index,explanation) values ('00000000-0000-0000-0000-000000000003','أي دواء ممنوع دمجه مع nitrates في علاج ضعف الانتصاب؟','["Sildenafil","Paracetamol","Omeprazole","Ferrous sulfate"]'::jsonb,0,'PDE-5 inhibitors مثل sildenafil قد تسبب هبوط ضغط خطير مع nitrates.') on conflict (id) do update set question=excluded.question,answers=excluded.answers,correct_index=excluded.correct_index,explanation=excluded.explanation;
insert into public.quiz_questions(id,question,answers,correct_index,explanation) values ('00000000-0000-0000-0000-000000000004','ما الرسالة الأساسية عند استخدام inhaled corticosteroid؟','["هو دواء إنقاذ فوري","تقنية الاستنشاق والالتزام مهمان","يُستخدم مرة واحدة فقط في العمر","لا داعي لغسل الفم"]'::jsonb,1,'التحكم في الربو يعتمد على الاستخدام الصحيح والالتزام بالعلاج الوقائي.') on conflict (id) do update set question=excluded.question,answers=excluded.answers,correct_index=excluded.correct_index,explanation=excluded.explanation;
insert into public.quiz_questions(id,question,answers,correct_index,explanation) values ('00000000-0000-0000-0000-000000000005','أي دواء يحتاج الانتباه إلى خطر نقص البوتاسيوم بسبب diuresis؟','["Furosemide","Omeprazole","Clotrimazole","Tamsulosin"]'::jsonb,0,'Loop diuretics مثل furosemide قد تسبب فقد البوتاسيوم.') on conflict (id) do update set question=excluded.question,answers=excluded.answers,correct_index=excluded.correct_index,explanation=excluded.explanation;
insert into public.quiz_questions(id,question,answers,correct_index,explanation) values ('00000000-0000-0000-0000-000000000006','أي مجموعة تمثل ACE inhibitor + ARB + ARNI؟','["Lisinopril + valsartan + sacubitril/valsartan","Amlodipine + furosemide + aspirin","Metformin + insulin + sitagliptin","Warfarin + heparin + aspirin"]'::jsonb,0,'هذه الفئات تعمل على محور renin-angiotensin، والـARNI يجمع neprilysin inhibition مع ARB.') on conflict (id) do update set question=excluded.question,answers=excluded.answers,correct_index=excluded.correct_index,explanation=excluded.explanation;
insert into public.quiz_questions(id,question,answers,correct_index,explanation) values ('00000000-0000-0000-0000-000000000007','ما أبرز نقطة تعليمية مع inhaled corticosteroids؟','["غسول الفم بعد الاستخدام","يُستخدم فقط عند نوبة حادة","لا يحتاج تقنية صحيحة","يمنع كل أنواع العدوى"]'::jsonb,0,'المضمضة بعد الاستخدام تقلل خطر oral candidiasis، وتقنية الاستنشاق ضرورية.') on conflict (id) do update set question=excluded.question,answers=excluded.answers,correct_index=excluded.correct_index,explanation=excluded.explanation;
insert into public.quiz_questions(id,question,answers,correct_index,explanation) values ('00000000-0000-0000-0000-000000000008','أي دواء من الخيارات يرفع خطر serotonin syndrome مع tramadol؟','["Sertraline","Omeprazole","Amlodipine","Calcium carbonate"]'::jsonb,0,'Sertraline يزيد serotonergic burden مع tramadol.') on conflict (id) do update set question=excluded.question,answers=excluded.answers,correct_index=excluded.correct_index,explanation=excluded.explanation;
insert into public.quiz_questions(id,question,answers,correct_index,explanation) values ('00000000-0000-0000-0000-000000000009','أي علامة تجعل NSAID أكثر خطورة؟','["تاريخ قرحة/نزف هضمي","شعر طويل","قصر النظر فقط","عدم شرب القهوة"]'::jsonb,0,'NSAIDs قد تسبب قرحة ونزف، ويزداد الخطر مع التاريخ السابق وعوامل أخرى.') on conflict (id) do update set question=excluded.question,answers=excluded.answers,correct_index=excluded.correct_index,explanation=excluded.explanation;
insert into public.quiz_questions(id,question,answers,correct_index,explanation) values ('00000000-0000-0000-0000-000000000010','ما الترياق المعروف لتسمم paracetamol؟','["N-acetylcysteine","Flumazenil","Protamine","Naloxone"]'::jsonb,0,'N-acetylcysteine يعيد glutathione ويساعد على إزالة NAPQI.') on conflict (id) do update set question=excluded.question,answers=excluded.answers,correct_index=excluded.correct_index,explanation=excluded.explanation;
insert into public.site_content(id,config) values ('global','{}'::jsonb) on conflict (id) do nothing;
